NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Joshua'

CHAPTERS = {
    1: {
        1: 'Und es geschah nach dem Tode Moses, des Knechtes Jehovahs, daß Jehovah zu Joschua, dem Sohne Nuns, Moses Diener, sprach und sagte:',
        2: 'Mose, mein Knecht, ist tot, und nun mache du dich auf, gehe über diesen Jordan, du und all dies Volk, nach dem Lande, das Ich ihnen, den Söhnen Israels gebe.',
        3: 'Jeder Ort, darauf eure Fußsohle tritt, habe Ich euch gegeben, wie Ich zu Mose geredet habe.',
        4: 'Von der Wüste und diesem Libanon und bis zu dem großen Flusse, dem Flusse Euphrat, alles Land der Chethiter und bis zum großen Meer, zum Untergang der Sonne, soll eure Grenze sein.',
        5: 'Kein Mensch soll bestehen vor dir alle Tage deines Lebens. Wie Ich mit Mose war, will Ich mit dir sein, und dich nicht aufgeben, noch dich verlassen.',
        6: 'Sei stark und rüstig; denn du sollst diesem Volk das Land, das Ich ihren Vätern geschworen habe, ihnen zu geben, als Erbe austeilen.',
        7: 'Sei nur stark und sehr rüstig, daß du haltest zu tun nach all dem Gesetz, das dir Mose, Mein Knecht, geboten hat. Weiche nicht ab davon, weder zur Rechten, noch zur Linken, auf daß du klüglich handelst überall, wo du hingehst.',
        8: 'Laß dieses Gesetzbuch nicht von deinem Munde weichen und sinne darüber Tag und Nacht, auf daß du haltest zu tun nach allem, das darin geschrieben ist; denn dann gelingt dir es auf deinem Wege, und dann handelst du klüglich.',
        9: 'Habe Ich dir nicht geboten, du sollest stark sein und rüstig, sollst kein Grauen und kein Entsetzen haben?, denn Jehovah, dein Gott, ist mit dir, überall wo du hingehst.',
        10: 'Und Joschua gebot den Vorstehern des Volkes und sprach:',
        11: 'Gehet hin mitten durch das Lager und gebietet dem Volke und sprechet: Bereitet euch Zehrung; denn in noch drei Tagen ziehet ihr über diesen Jordan, daß ihr hineinkommt und das Land einnehmet, das Jehovah, euer Gott, euch zum Erbbesitze gibt.',
        12: 'Und zu den Rubeniten und den Gaditern und zu dem halben Stamm Menascheh sprach Joschua und sagte:',
        13: 'Gedenket des Wortes, das euch Mose, der Knecht Jehovahs, geboten hat und gesagt: Jehovah, euer Gott, hat euch zur Ruhe gebracht und euch dies Land gegeben;',
        14: 'Eure Weiber, eure Kindlein und eure Viehherden dürfen in dem Lande bleiben, das euch Mose diesseits des Jordans gegeben hat. Ihr aber sollt kampfgerüstet vor euren Brüdern hinüberziehen, alle tapferen Männer, und sollt ihnen beistehen.',
        15: 'Bis daß Jehovah eure Brüder wie euch zur Ruhe gebracht hat, und auch sie das Land eingenommen haben, das Jehovah, euer Gott, ihnen gibt. Dann dürft ihr in das Land eures Erbbesitzes zurückkehren und dasselbe erblich besitzen, das euch Mose, der Knecht Jehovahs, diesseits des Jordans gegen Aufgang der Sonne gegeben hat.',
        16: 'Und sie antworteten Joschua und sprachen: Alles, was du uns geboten hast, wollen wir tun, und wohin du uns sendest, wollen wir gehen.',
        17: 'Ganz so, wie wir auf Mose hörten, so werden wir auf dich hören. Nur möge Jehovah, dein Gott, mit dir sein, wie Er mit Mose gewesen ist.',
        18: 'Jeder Mann, der deinem Mund widerspenstig ist und nicht hört auf deine Worte in allem, das du uns gebietest, der soll getötet werden. Nur sei stark und rüstig.',
    },
    2: {
        1: 'Und Joschua, der Sohn Nuns, sandte im Stillen von Schittim zwei Männer als Kundschafter und sagte ihnen: Gehet, beseht das Land und Jericho. Und sie gingen und kamen in das Haus eines Weibes, einer Buhlerin, und ihr Name war Rachab, und sie legten sich da nieder.',
        2: 'Und sie sagten dem Könige von Jericho und sprachen: Siehe, es sind in dieser Nacht Männer von den Söhnen Israels hierher hereingekommen, um das Land auszuforschen.',
        3: 'Und der König von Jericho sandte zu Rachab und sprach: Bringe die Männer, die zu dir hereingekommen, heraus, die in dein Haus eingegangen; denn sie sind hereingekommen, das ganze Land auszuforschen.',
        4: 'Das Weib aber nahm die zwei Männer und verbarg sie und sagte: Es ist also, die Männer sind hereingekommen; aber ich wußte nicht, von wannen sie waren.',
        5: 'Und als man das Tor schließen wollte in der Finsternis, gingen die Männer hinaus; ich weiß nicht, wohin die Männer gegangen sind. Setzet ihnen eilends nach; denn ihr werdet sie erreichen.',
        6: 'Sie hatte sie aber auf das Dach hinaufsteigen lassen und mit Flachsstengeln verdeckt, die auf dem Dach von ihr waren zurechtgelegt worden.',
        7: 'Und die Männer setzten ihnen nach auf dem Wege nach dem Jordan, nach den Furten, und sie schlossen das Tor hinter ihnen zu, da die hinausgegangen waren, die ihnen nachsetzten.',
        8: 'Ehe sie sich aber niederlegten, da stieg sie zu ihnen hinauf auf das Dach,',
        9: 'Und sprach zu den Männern: Ich weiß, daß Jehovah euch das Land gegeben hat, und daß ein Schrecken vor euch auf uns gefallen ist, und alle Einwohner des Landes vor euch zerfließen.',
        10: 'Denn wir haben gehört, wie Jehovah die Wasser des Schilfmeeres vor euch vertrocknete, als ihr aus Ägypten auszogt, und was ihr den zwei Königen des Amoriters, dem Sichon und dem Og, jenseits des Jordans getan, die ihr verbannt habt.',
        11: 'Und wir haben es gehört, und nun ist unser Herz zerschmolzen und der Geist ist in keinem Mann mehr aufrecht vor euch; denn Jehovah, euer Gott, Welcher ist Gott in den Himmeln oben und auf Erden unten.',
        12: 'Und nun schwöret mir doch bei Jehovah, daß, wie ich an euch Barmherzigkeit getan, so auch ihr Barmherzigkeit tut an dem Hause meines Vaters; und gebet mir ein Zeichen der Wahrheit,',
        13: 'Daß ihr meinen Vater und meine Mutter und meine Brüder und meine Schwestern und alles, was sie haben, am Leben lasset und unsere Seelen vom Tode errettet.',
        14: 'Und die Männer sprachen zu ihr: Unsere Seele sei statt eurer des Todes. Wenn ihr dies, unsere Sache nicht ansaget, so soll geschehen, daß wir, wenn Jehovah uns das Land gibt, Barmherzigkeit und Wahrheit an dir tun.',
        15: 'Und sie ließ dieselben an einem Stricke durch das Fenster hinab; denn ihr Haus war mit der Wand in der Stadtmauer, und in der Stadtmauer wohnte sie.',
        16: 'Und sie sagte ihnen: Gehet nach dem Berge, daß, die euch nachsetzen, nicht auf euch stoßen, und versteckt euch dort drei Tage, bis die euch nachsetzen, zurückkehren, und hernach geht eures Weges.',
        17: 'Und die Männer sprachen zu ihr: Wir sind dieses deines Schwures ledig, den du uns hast schwören lassen.',
        18: 'Siehe, so wir kommen in das Land, sollst du diese Schnur von Scharlachfaden in das Fenster binden, durch das du uns herabgelassen hast, und deinen Vater und deine Mutter und deine Brüder und das ganze Haus deines Vaters zu dir ins Haus versammeln.',
        19: 'Und es geschehe, daß jeder, der aus der Tür deines Hauses hinaus auf die Gasse geht, dessen Blut sei auf seinem Haupt, und wir sind unschuldig. Jeder aber, der bei dir im Hause ist, dessen Blut komme auf unser Haupt, so eine Hand wider ihn sein wird.',
        20: 'Und wenn du diese unsere Sache ansagst, so sind wir ledig des Schwures, den du uns schwören ließest.',
        21: 'Und sie sprach: Nach euren Worten, so sei es! Und sie entließ dieselben und sie gingen; sie aber band die Scharlachschnur in das Fenster.',
        22: 'Und sie gingen und kamen auf den Berg und blieben allda drei Tage, bis die, so ihnen nachgesetzt, zurückgekehrt waren. Und die, so ihnen nachgesetzt, hatten auf dem ganzen Wege gesucht und sie nicht gefunden.',
        23: 'Und die zwei Männer kehrten zurück und kamen vom Berge herab und setzten über und kamen zu Joschua, dem Sohne Nuns und erzählten ihm alles, was sie betroffen hatte;',
        24: 'Und sprachen zu Joschua: Jehovah hat das ganze Land in unsre Hand gegeben; und alle Einwohner des Landes zerfließen auch vor uns.',
    },
    3: {
        1: 'Und Joschua stand früh am Morgen auf, und sie brachen auf von Schittim und kamen an den Jordan, er und alle Söhne Israels und übernachteten allda, ehe sie hinüberzogen.',
        2: 'Und es geschah am Ende dreier Tage, daß die Vorsteher inmitten des Lagers durchgingen,',
        3: 'Und geboten dem Volk und sprachen: Wenn ihr die Bundeslade Jehovahs, eures Gottes, sehet und die Priester, die Leviten, sie tragen, so brechet auf von eurem Orte und gehet ihr nach.',
        4: 'Doch soll zwischen euch und zwischen ihr eine Entfernung sein, bei zweitausend Ellen gemessen. Kommt ihr nicht nahe, auf daß ihr den Weg wisset, auf dem ihr gehen sollt; denn ihr seid des Weges nicht hinübergezogen gestern oder ehegestern.',
        5: 'Und Joschua sprach zum Volke: Heiligt euch; denn morgen wird Jehovah in eurer Mitte Wunder tun.',
        6: 'Und zu den Priestern sprach Joschua und sagte: Traget die Bundeslande und ziehet vor dem Volke hinüber, und sie trugen die Bundeslade und zogen vor dem Volke hin.',
        7: 'Und Jehovah sprach zu Joschua: An diesem Tage will Ich anfangen, dich groß zu machen in den Augen von ganz Israel, auf daß sie wissen, daß, wie Ich mit Mose war, so Ich mit dir sein werde.',
        8: 'Und du gebiete den Priestern, so die Bundeslade tragen, und sprich: Wenn ihr an den Rand der Wasser des Jordans kommt, so sollt ihr im Jordan stehen.',
        9: 'Und Joschua sprach zu den Söhnen Israel: Tretet hier herzu und höret die Worte Jehovahs, eures Gottes!',
        10: 'Und Joschua sprach: Daran sollt ihr wissen, daß ein lebendiger Gott in eurer Mitte ist, und daß Er den Kanaaniter und den Chethiter und den Chiviter und den Pherisiter und den Girgaschiter und den Amoriter und den Jebusiter vor euch austreibt.',
        11: 'Siehe, die Bundeslade des Herrn der ganzen Erde zieht vor euch hinüber im Jordan.',
        12: 'Und nun nehmet euch zwölf Männer aus den Stämmen Israels, aus jedem Stamm je einen Mann.',
        13: 'Und es wird geschehen, sowie die Sohlen der Füße der Priester, so die Lade Jehovahs, des Herrn der ganzen Erde, tragen, in den Wassern des Jordans ruhen, so werden die Wasser des Jordans abgeschnitten und die Wasser, die von oben herabkommen, werden wie ein Haufen.',
        14: 'Und es geschah, als das Volk aufbrach aus seinen Zelten, um über den Jordan zu setzen, und die Priester, so die Bundeslade vor dem Volke trugen,',
        15: 'Und wie die Träger der Lade bis an den Jordan kamen, und die Füße der Priester, welche die Lade trugen, ins Ende des Wassers sich tauchten, - der Jordan aber ist voll über allen seinen Ufern alle Tage der Ernte -,',
        16: 'Da standen die Wasser, die von oben herabkamen, sie richteten sich auf in einen Haufen, sehr fern von der Stadt Adam, die zur Seite von Zarthan ist, und die Wasser, so zum Meer der Arabah, zum Salzmeer hinabgingen wurden alle, sie wurden abgeschnitten, und das Volk zog hinüber, gegenüber von Jericho.',
        17: 'Die Priester aber, welche die Bundeslade Jehovahs trugen, standen fest im Trockenen mitten im Jordan. Und ganz Israel ging im Trockenen durch, bis daß die ganze Völkerschaft den Durchzug des Jordans vollendet hatte.',
    },
    4: {
        1: 'Und es geschah, wie die ganze Völkerschaft allesamt über den Jordan gegangen war, daß Jehovah zu Joschua sprach und sagte:',
        2: 'Nehmet euch aus dem Volk zwölf Männer, je einen Mann aus einem Stamm.',
        3: 'Und gebietet ihnen und sprechet: Hebt euch auf hier mitten aus dem Jordan, von der Stelle, wo die Füße der Priester festgestanden, zwölf Steine, und bringt sie mit euch hinüber und legt sie nieder an dem Nachtlager, darin ihr über Nacht bleibt diese Nacht.',
        4: 'Und Joschua rief den zwölf Männer aus den Söhnen Israels, die er bereit hatte, je einen Mann aus einem Stamm.',
        5: 'Und Joschua sprach zu ihnen: Gehet hinüber vor der Lade Jehovahs, eures Gottes, mitten in den Jordan, und hebt euch empor jeder Mann einen Stein auf seine Schulter nach der Zahl der Stämme der Söhne Israels.',
        6: 'Auf daß dies ein Zeichen sei in eurer Mitte, wenn eure Söhne euch morgen fragen und sagen: Was sollen euch diese Steine?',
        7: 'Da sollt ihr ihnen sagen, wie die Wasser des Jordans abgeschnitten wurden vor der Bundeslande Jehovahs, daß bei ihrem Übergang durch den Jordan die Wasser des Jordans abgeschnitten wurden, und daß diese Steine für die Söhne Israels seien ewiglich zum Andenken.',
        8: 'Und die Söhne Israels taten also, wie ihnen Joschua geboten hatte, und hoben zwölf Steine aus der Mitte des Jordans auf, wie Jehovah zu Joschua geredet, nach der Zahl der Stämme der Söhne Israel, und brachten sie mit sich hinüber nach dem Nachtlager und legten sie nieder allda.',
        9: 'Und Joschua richtete zwölf Steine auf mitten im Jordan, an der Stelle der Füße der Priester, so die Bundeslade trugen, und sie sind dort bis auf diesen Tag.',
        10: 'Und die Priester, welche die Lade trugen, standen mitten im Jordan, bis daß alles getan war, das Jehovah dem Joschua geboten hatte, zu dem Volke zu reden, nach allem, das Mose dem Joschua geboten hatte; und das Volk eilte und zog hindurch.',
        11: 'Und es geschah, als das ganze Volk allesamt hindurchgegangen war, daß auch die Lade Jehovahs hindurchging und die Priester, angesichts des Volkes.',
        12: 'Und die Söhne Rubens und die Söhne Gads und der halbe Stamm Menaschehs zogen kampfgerüstet vor den Söhnen Israels hinüber, wie Mose zu ihnen geredet hatte.',
        13: 'Bei vierzigtausend, zum Heere ausgerüstet, zogen hinüber vor Jehovah zum Streite auf Jerichos Flachland.',
        14: 'An jenem Tage machte Jehovah den Joschua groß vor den Augen von ganz Israel, und sie fürchteten ihn, wie sie Mose gefürchtet hatten, alle Tage seines Lebens.',
        15: 'Und Jehovah sprach zu Joschua und sagte:',
        16: 'Gebiete den Priestern, welche die Lade des Zeugnisses tragen, daß sie aus dem Jordan heraufsteigen;',
        17: 'Und Joschua gebot den Priestern und sprach: Steiget herauf aus dem Jordan.',
        18: 'Und es geschah, als die Priester, welche die Bundeslade Jehovahs trugen, heraufstiegen aus der Mitte des Jordans, als die Fußsohlen der Priester auf das Trockene sich herauszogen, da kehrten die Wasser des Jordans an ihren Ort zurück und gingen wie gestern und ehegestern, über alle seine Ufer.',
        19: 'Und das Volk kam herauf aus dem Jordan am zehnten des ersten Monats und sie lagerten in Gilgal an der Grenze Jerichos gegen Aufgang.',
        20: 'Und jene zwölf Steine, die sie aus dem Jordan genommen, richtete Joschua in Gilgal auf;',
        21: 'Und er sprach zu den Söhnen Israels und sagte: So eure Söhne morgen ihre Väter fragen werden und sagen: Was sollen diese Steine?',
        22: 'So sollt ihr eure Söhne wissen lassen und ihnen sagen: Im Trockenen ist Israel durch den Jordan da durchgezogen.',
        23: 'Weil Jehovah, euer Gott, die Wasser des Jordans vor euch vertrocknet hatte, bis ihr durchgezogen waret, gleich wie Jehovah, euer Gott, mit dem Schilfmeere tat, das Er vor uns vertrocknete, bis wir durchgezogen.',
        24: 'Auf daß alle Völker der Erde erkennen die Hand Jehovahs, daß sie stark ist, auf daß ihr Jehovah, euren Gott, fürchtet alle Tage.',
    },
    5: {
        1: 'Und es geschah, da alle die Könige der Amoriter diesseits des Jordans nach dem Meere hin und alle die Könige der Kanaaniter am Meere hörten, wie Jehovah die Wasser des Jordans vor den Söhnen Israels vertrocknete, bis sie durchgezogen waren, da zerschmolz ihr Herz und es war kein Geist mehr in ihnen vor den Söhnen Israels.',
        2: 'Zu selbiger Zeit sprach Jehovah zu Joschua: Mache dir steinerne Messer und beschneide wieder die Söhne Israels zum zweiten Male.',
        3: 'Und Joschua machte sich steinerne Messer und beschnitt die Söhne Israels am Hügel Araloth.',
        4: 'Und so ist die Sache, daß Joschua sie beschnitt: Alles Volk, das aus Ägyptenland ausgezogen, die Männlichen, alle Männer des Streites, waren in der Wüste gestorben, auf dem Wege, da sie aus Ägypten auszogen.',
        5: 'Denn alles Volk, das auszog, war beschnitten, aber alles Volk, das in der Wüste auf dem Wege, da man auszog aus Ägypten, geboren worden, war nicht beschnitten.',
        6: 'Denn vierzig Jahre zogen die Söhne Israels in der Wüste, bis die ganze Völkerschaft alle war, die Männer des Streites, die aus Ägypten auszogen, weil sie nicht auf die Stimme Jehovahs gehört; weshalb ihnen Jehovah schwur, daß Er sie nicht wollte sehen lassen das Land, das uns zu geben Jehovah ihren Vätern geschworen hatte, ein Land, das mit Milch und Honig fließt.',
        7: 'Und er ließ aufstehen ihre Söhne an ihrer Statt; sie beschnitt Joschua; denn sie hatten Vorhaut, weil man sie auf dem Wege nicht beschnitt.',
        8: 'Und es geschah, als er beendigt hatte die ganze Völkerschaft zu beschneiden, daß sie an ihrer Stelle im Lager blieben, bis sie genesen waren.',
        9: 'Und Jehovah sprach zu Joschua: Heute habe Ich die Schmach Ägyptens von euch gewälzt; und man nannte den Namen jenes Ortes Gilgal bis auf diesen Tag.',
        10: 'Und die Söhne Israels lagerten in Gilgal und begingen das Passah, am vierzehnten Tage des Monats am Abend im Flachland Jerichos;',
        11: 'Und sie aßen von der Frucht des Landes vom morgenden Tage nach dem Passah, Ungesäuertes und Geröstetes, an eben dem Tage;',
        12: 'Und das Mannah hörte auf am morgenden Tag, da sie von der Frucht des Landes aßen; und die Söhne Israel hatten kein Mannah mehr; sondern sie aßen von dem Ertrag des Landes Kanaan in demselbigen Jahr.',
        13: 'Und es geschah, als Joschua bei Jericho war, daß er seine Augen aufhob und sah, und siehe, ein Mann stand ihm gegenüber und Sein gezücktes Schwert in Seiner Hand. Und Joschua ging zu Ihm und sprach zu Ihm: Bist Du für uns oder für unsere Dränger?',
        14: 'Und Er sprach zu ihm: Nicht doch! Ich bin der Oberste des Heeres Jehovahs, jetzt komme Ich. Und Joschua fiel auf sein Angesicht zur Erde und betete an und sprach zu Ihm: Was redet Mein Herr zu Seinem Knechte?',
        15: 'Und der Oberste des Heeres Jehovahs sprach zu Joschua: Ziehe ab deinen Schuh von deinem Fuß; denn der Ort, auf dem du stehst, ist heilig. Und Joschua tat also.',
    },
    6: {
        1: 'Und Jericho hatte geschlossen und war verschlossen vor den Söhnen Israels. Niemand kam heraus und niemand ging hinein.',
        2: 'Und Jehovah sprach zu Joschua: Siehe, Ich habe Jericho und seinen König samt den Mächtigen seiner Streitmacht in deine Hand gegeben.',
        3: 'Und ihr sollt die Stadt umziehen, all ihr Männer des Streites, umringen die Stadt einmal; sechs Tage sollst du also tun.',
        4: 'Und sieben Priester sollen sieben Jubelposaunen vor der Lade tragen. Und am siebenten Tage sollt ihr siebenmal die Stadt umziehen und die Priester in die Posaunen stoßen.',
        5: 'Und es soll geschehen, wenn das Jubelhorn geblasen wird und ihr die Stimme der Posaune hört, so soll alles Volk mit großem Jubelruf jubeln, und die Mauer der Stadt wird fallen unter sich, und das Volk soll hinaufziehen, jeder Mann vor sich hin.',
        6: 'Und Joschua, der Sohn Nuns, rief die Priester und sprach zu ihnen: Traget die Bundeslade und sieben Priester sollen sieben Jubelposaunen vor der Lade Jehovahs tragen.',
        7: 'Und zum Volke sprach er: Ziehet hin und umziehet die Stadt, und der Ausgerüstete ziehe her vor der Lade Jehovahs!',
        8: 'Und es geschah, als Joschua zum Volke gesprochen hatte, daß die sieben Priester, welche die sieben Jubelposaunen vor Jehovah trugen, hinzogen und in die Posaunen stießen, und die Bundeslade Jehovahs hinter ihnen herging.',
        9: 'Der Ausgerüstete aber ging hin vor den Priestern, welche in die Posaune stießen und der Nachzug ging hinter der Lade, und sie gingen und stießen in die Posaunen.',
        10: 'Und dem Volke hatte Joschua geboten und gesagt: Ihr sollt nicht jubeln und eure Stimme nicht hören lassen, und kein Wort soll aus eurem Munde gehen, bis zum Tage, da ich euch sage: Jubelt! Dann sollt ihr jubeln.',
        11: 'Und die Lade Jehovahs umzog einmal die Stadt, sie umringend; und sie kamen in das Lager und blieben über die Nacht im Lager.',
        12: 'Und Joschua machte sich früh am Morgen auf, und die Priester trugen die Lade Jehovahs.',
        13: 'Und es gingen hin, die sieben Priester, welche die sieben Jubelposaunen vor der Lade Jehovahs trugen, sie gingen hin und stießen in die Posaunen, und der Ausgerüstete ging vor ihnen her, und der Nachzug ging hinter der Lade Jehovahs, sie zogen und stießen in die Posaunen.',
        14: 'Und am zweiten Tage umzogen sie einmal die Stadt und kehrten in das Lager zurück. So taten sie sechs Tage.',
        15: 'Und es geschah am siebenten Tage, daß sie früh aufstanden, da die Morgenröte aufging und nach dieser Weise siebenmal um die Stadt zogen. Nur an diesem Tage zogen sie siebenmal rings um die Stadt.',
        16: 'Und es geschah beim siebenten Male, daß die Priester in die Posaunen stießen, und Joschua sprach zu dem Volke: Jubelt; denn Jehovah hat euch die Stadt gegeben!',
        17: 'Und die Stadt sei, sie und alles, was in ihr ist, dem Jehovah verbannt! Nur die Buhlerin Rachab, sie und alles, was bei ihr im Haus ist, soll am Leben bleiben, weil sie die Boten, die wir sandten, versteckt hat.',
        18: 'Hütet euch aber nur vor dem Verbannten, daß ihr euch nicht verbannt und nehmet vom Verbannten, daß ihr nicht das Lager Israels in Verbann bringt und es zerrüttet.',
        19: 'Aber alles Silber und Gold und das eherne und eiserne Gerät soll Jehovah geheiligt sein, es soll in den Schatz Jehovahs kommen.',
        20: 'Und das Volk jubelte und sie stießen in die Posaunen; und es geschah, als das Volk den Schall der Posaune hörte, und das Volk mit großem Jubelruf jubelte, da fiel die Mauer unter sich zusammen und das Volk ging hinauf in die Stadt, jeder Mann vor sich hin, und so eroberten sie die Stadt.',
        21: 'Und sie verbannten alles in der Stadt mit der Schärfe des Schwertes, vom Manne bis zum Weibe, vom Jungen bis zum Alten und zum Ochsen und Kleinvieh und Esel.',
        22: 'Und zu den zwei Männern, die das Land hatten ausgekundschaftet, sprach Joschua: Gehet hinein in das Haus des Weibes, der Buhlerin, und bringt von da heraus das Weib und alles, was sie hat, wie ihr derselben geschworen habt.',
        23: 'Und die Jünglinge, die Kundschafter, gingen hinein und brachten die Rachab und ihren Vater und ihre Mutter und ihre Brüder und alles, das sie hatte, heraus; und sie brachten ihre ganze Familie heraus und ließen sie außerhalb des Lagers Israels.',
        24: 'Und die Stadt verbrannten sie mit Feuer und alles, was darin war. Nur das Silber und das Gold und die ehernen und eisernen Geräte gaben sie in den Schatz des Hauses Jehovahs.',
        25: 'Und Rachab, die Buhlerin, und ihres Vaters Haus und alles, was sie hatte, ließ Joschua am Leben und sie wohnte inmitten Israels bis auf diesen Tag, dafür, daß sie die Boten, die Joschua gesandt, um Jericho auszukundschaften, versteckt hatte.',
        26: 'Und Joschua schwur zur selben Zeit und sprach: Verflucht sei der Mann vor Jehovah, der aufsteht und diese Stadt Jericho baut. Um seinen Erstgeborenen soll er sie gründen, und um seinen Jüngstgeborenen ihre Tore einsetzen!',
        27: 'Und Jehovah war mit Joschua, und im ganzen Lande war das Gerüchte ihm.',
    },
    7: {
        1: 'Und die Söhne Israels begingen Untreue an dem Verbannten; und Achan, der Sohn Karmis, des Sohnes Sabdis, des Sohnes Serachs, vom Stamme Judah, nahm von dem Verbannten. Und der Zorn Jehovahs entbrannte wider die Söhne Israels.',
        2: 'Und Joschua sandte Männer aus von Jericho nach Ai, das bei Beth Aven östlich von Bethel ist, und sprach zu ihnen und sagte: Ziehet hinauf und kundschaftet das Land aus. Und die Männer gingen hinauf und kundschafteten Ai aus.',
        3: 'Und sie kehrten zu Joschua zurück und sprachen zu ihm: Laß nicht das ganze Volk hinaufziehen. Bei zweitausend Mann oder bei dreitausend Mann mögen hinaufziehen und Ai schlagen. Bemühe nicht das ganze Volk dahin; denn ihrer sind wenige.',
        4: 'Und es zogen vom Volke bei dreitausend Mann dort hinauf, aber sie flohen vor den Männern von Ai.',
        5: 'Und die Männer von Ai schlugen ihrer bei sechsunddreißig Mann und setzten ihnen nach vor das Tor bis Schebarim, und schlugen sie beim Hinabgehen. Und dem Volke zerschmolz das Herz und ward zu Wasser.',
        6: 'Und Joschua zerriß seine Gewänder und fiel auf sein Angesicht zur Erde vor der Lade Jehovahs bis zum Abend, er und die Ältesten Israels und taten Staub auf ihr Haupt.',
        7: 'Und Joschua sprach: Ach, Herr, Jehovah! Warum ließest Du doch dieses Volk über den Jordan herüberziehen, um uns in die Hand des Amoriters zu geben und uns zu zerstören! Hätten wir doch jenseits des Jordans bleiben wollen!',
        8: 'Bitte, Herr, was soll ich sagen, nachdem Israel vor seinen Feinden den Rücken gekehrt hat?',
        9: 'Und der Kanaaniter und alle Einwohner des Landes werden es hören, und uns umgeben und unseren Namen von der Erde ausrotten. Und was wirst Du für deinen großen Namen tun?',
        10: 'Und Jehovah sprach zu Joschua: Stehe auf! Was fällst du da auf dein Angesicht?',
        11: 'Israel hat gesündigt und sie haben auch Meinen Bund überschritten, den Ich ihnen geboten; und sie haben auch von dem Verbannten genommen, und haben auch gestohlen, sie haben es auch abgeleugnet und es auch in ihr Gerät getan.',
        12: 'Und die Söhne Israels vermögen nicht aufzustehen vor ihren Feinden, sie müssen vor ihren Feinden den Rücken wenden; denn sie sind im Bann. Ich werde ferner nicht mit euch sein, wenn ihr den Bann nicht aus eurer Mitte vernichtet.',
        13: 'Stehe auf, heilige das Volk und sprich: Heiligt euch auf morgen; denn also spricht Jehovah, der Gott Israels: Ein Bann ist in deiner Mitte, Israel. Du vermagst nicht aufzustehen vor deinen Feinden, bis ihr den Bann aus eurer Mitte tut.',
        14: 'Am Morgen aber sollt ihr nahen nach euren Stämmen, und es soll geschehen, daß der Stamm, den Jehovah herausnimmt, nahe nach seinen Familien, und die Familie, die Jehovah herausnimmt, soll nahen nach den Häusern, und das Haus, das Jehovah herausnimmt, soll nahen nach den Männern.',
        15: 'Und es soll geschehen, daß der, als im Bann herausgenommen wird, mit Feuer verbrannt werde, er und all das Seine, weil er den Bund Jehovahs überschritten und eine Torheit in Israel getan hat.',
        16: 'Und Joschua stand früh am Morgen auf und ließ Israel nach seinen Stämmen nahen, und der Stamm Judah ward herausgenommen.',
        17: 'Und er ließ die Familien Judahs nahen und die Familie der Sarchiten ward herausgenommen; und er ließ die Familie der Sarchiten nahen nach den Männern, und Sabdi ward herausgenommen.',
        18: 'Und er ließ nahen sein Haus nach den Männern, und es ward herausgenommen Achan, der Sohn Karmis, des Sohnes Serach, vom Stamme Judah.',
        19: 'Und Joschua sprach zu Achan: Mein Sohn, gib Jehovah, dem Gotte Israels die Ehre, und gib Ihm ein Bekenntnis, und sage mir doch an, was du getan hast und verhehle es nicht vor mir.',
        20: 'Und Achan antwortete dem Joschua und sprach: In Wahrheit, ich habe gesündigt an Jehovah, dem Gott Israels und so und so habe ich getan;',
        21: 'Und ich sah unter der Beute einen guten Mantel aus Schinear und zweihundert Schekel Silber und eine Barre Goldes, fünfzig Schekel sein Gewicht. Und ich begehrte danach, und ich nahm sie. Und siehe, sie sind in der Erde verdeckt in der Mitte meines Zeltes, und das Silber darunter.',
        22: 'Und Joschua sandte Boten, und sie liefen nach dem Zelt, und siehe, es war verdeckt in seinem Zelt, und das Silber darunter.',
        23: 'Und sie nahmen dieselben aus der Mitte des Zeltes und brachten sie herein zu Joschua und zu allen Söhnen Israels und schütteten sie aus vor Jehovah.',
        24: 'Und Joschua nahm den Achan, den Sohn Serachs, und das Silber und den Mantel und die Zunge Goldes und seine Söhne und seine Töchter und seinen Ochsen und seinen Esel und sein Kleinvieh und sein Zelt und alles, was er hatte, und ganz Israel mit ihm brachten sie hinauf in den Talgrund Achor.',
        25: 'Und Joschua sprach: Wie du uns zerrüttet, so zerrütte dich Jehovah an diesem Tage. Und ganz Israel steinigte ihn mit Steinen und sie verbrannten sie mit Feuer und warfen Steine auf sie.',
        26: 'Und sie errichteten über ihm einen großen Steinhaufen bis auf diesen Tag. Und Jehovah kehrte Sich zurück von der Entbrennung Seines Zornes. Darum nennt man den Namen selbigen Ortes Emek Achor bis auf diesen Tag.',
    },
    8: {
        1: 'Und Jehovah sprach zu Joschua: Fürchte dich nicht und entsetze dich nicht. Nimm alles Kriegsvolk mit dir und mache dich auf und zieh hinauf nach Ai. Siehe, Ich habe den König von Ai und sein Volk und seine Stadt und sein Land in deine Hand gegeben.',
        2: 'Und du sollst mit Ai und seinem Könige tun, wie du mit Jericho und seinem Könige getan, nur möget ihr ihre Beute und ihr Vieh für euch rauben. Lege dir einen Hinterhalt für die Stadt hinter ihr.',
        3: 'Und Joschua machte sich auf und alles Kriegsvolk, um nach Ai hinaufzuziehen. Und Joschua erwählte sich dreißigtausend Mann, Helden der Tapferkeit, und sandte sie ab in der Nacht;',
        4: 'Und er gebot ihnen und sprach: Sehet, ihr sollt wider die Stadt im Hinterhalte liegen hinter der Stadt. Entfernt euch nicht zu sehr von der Stadt, und seid allesamt bereit.',
        5: 'Ich aber und alles Volk, das mit mir ist, wir werden uns der Stadt nähern, und wenn sie ausgehen uns entgegen wie zuerst, so werden wir vor ihnen fliehen.',
        6: 'Und sie werden ausziehen uns nach, bis wir sie von der Stadt abgezogen haben; denn sie werden sagen: Sie fliehen vor uns, wie zuerst. Und wir werden fliehen vor ihnen.',
        7: 'Ihr aber machet euch aus dem Hinterhalte auf und nehmt die Stadt ein. Und Jehovah, euer Gott, wird sie in eure Hand geben.',
        8: 'Und es geschehe, wenn ihr die Stadt gewonnen habt, dann sollt ihr die Stadt mit Feuer anzünden; nach dem Worte Jehovahs sollt ihr tun. Sehet, ich habe es euch geboten.',
        9: 'Und Joschua entließ sie und sie gingen in den Hinterhalt und blieben zwischen Bethel und Ai auf der Meerseite von Ai. Und Joschua blieb über Nacht inmitten des Volkes in dieser Nacht.',
        10: 'Und am Morgen stand Joschua früh auf, und musterte das Volk und zog hinauf, er und die Ältesten Jehovahs vor dem Volke nach Ai hinauf;',
        11: 'Und alles Kriegsvolk, das mit ihm war, zog hinauf, und sie traten herzu und kamen der Stadt gegenüber, und lagerten gen Mitternacht von Ai, und das Tal war zwischen ihm und Ai.',
        12: 'Und er nahm bei fünftausend Mann und legte sie zwischen Bethel und Ai auf der Meerseite von Ai in Hinterhalt.',
        13: 'Und so stellten sie das Volk, das ganze Lager, das gegen Mitternacht von der Stadt war, daß der hintere Teil auf der Meerseite der Stadt war, und Jehoschua zog in jener Nacht in die Mitte des Talgrundes.',
        14: 'Und es geschah, als der König von Ai es sah, eilten die Männer von der Stadt und standen früh auf und zogen aus, Israel entgegen, zum Streite, er und all sein Volk, zur bestimmten Zeit vor das Flachland; er wußte aber nicht, daß hinter der Stadt ein Hinterhalt gegen ihn war.',
        15: 'Und Jehoschua und ganz Israel wurden geschlagen vor ihnen, und sie flohen auf dem Wege nach der Wüste.',
        16: 'Und sie riefen alles Volk in der Stadt, hinter ihnen nachzusetzen, und sie setzten hinter dem Joschua nach und wurden von der Stadt abgezogen.',
        17: 'Und kein Mann verblieb in Ai und Bethel, der nicht ausgezogen wäre, hinter Israel her; und sie ließen die Stadt geöffnet und setzten hinter Israel nach.',
        18: 'Und Jehovah sprach zu Joschua: Recke den Wurfspieß in deiner Hand wider Ai aus; denn Ich will sie in deine Hand geben. Und Joschua reckte den Wurfspieß, den er in seiner Hand hatte, wider die Stadt aus.',
        19: 'Und der Hinterhalt stand eilig auf von seinem Orte und sie liefen, wie er seine Hand ausreckte, und kamen in die Stadt und eroberten sie; und sie eilten und steckten die Stadt mit Feuer an.',
        20: 'Und die Männer von Ai wandten sich um hinter sich und sahen, und siehe, der Rauch der Stadt stieg gen Himmel auf, und sie hatten nicht, wohin sie fliehen sollten, dahin oder dorthin, und das Volk, das nach der Wüste geflohen war, kehrte um wider die, so ihnen nachgesetzt hatten.',
        21: 'Und Joschua und ganz Israel sahen, daß der Hinterhalt die Stadt erobert hatte und daß der Rauch der Stadt aufging, und sie kehrten um und schlugen die Männer von Ai.',
        22: 'Und jene gingen aus der Stadt ihnen entgegen, so daß sie mitten zwischen Israel waren, die einen von hier und die anderen dorther; und sie schlugen sie, bis daß ihnen kein Rest verblieb, noch einer entkam.',
        23: 'Und den König von Ai erfaßten sie lebendig und ließen ihn dem Joschua nahen.',
        24: 'Und da Israel alle Einwohner von Ai auf dem Felde in der Wüste, wohin sie ihnen nachsetzten, vollends erwürgt hatte, und alle durch die Schärfe des Schwertes gefallen, so daß sie alle waren, da kehrte ganz Israel nach Ai zurück und sie schlugen es mit der Schärfe des Schwertes.',
        25: 'Und alle, die an jenem Tage gefallen waren, vom Manne bis zum Weibe, waren zwölftausend, alle Leute von Ai.',
        26: 'Und Joschua zog seine Hand, damit er den Wurfspieß ausreckte, nicht zurück, bis daß er alle Einwohner von Ai verbannt hatte.',
        27: 'Nur das Vieh und die Beute dieser Stadt nahm Israel als Raub für sich, nach dem Worte Jehovahs, das Er dem Joschua geboten hatte.',
        28: 'Und Ai verbrannte Joschua und machte es zu einem ewiglichen Schutthaufen, zur Verwüstung, bis auf diesen Tag.',
        29: 'Und den König von Ai hängte er an einem Baume auf bis zur Zeit des Abends, und da die Sonne unterging, gebot Joschua, daß sie seinen Leichnam vom Baume abnehmen und an den Eingang des Stadttores werfen sollten. Und sie richteten einen großen Steinhaufen über ihm, bis auf diesen Tag.',
        30: 'Nun baute Joschua Jehovah, dem Gotte Israels einen Altar auf dem Berge Ebal,',
        31: 'Wie Mose, der Knecht Jehovahs, den Söhnen Israels geboten hatte, wie geschrieben ist im Gesetzbuche Moses: einen Altar von ganzen Steinen, über die kein Eisen geschwungen ward, und sie opferten darauf Jehovah Brandopfer und schlachteten Dankopfer.',
        32: 'Und allda schrieb er auf die Steine eine Abschrift des Gesetzes Moses, das er vor den Söhnen Israels geschrieben hatte.',
        33: 'Und ganz Israel und seine Ältesten und Vorsteher und seine Richter standen auf beiden Seiten der Lade, gegenüber den Priestern, den Leviten, so die Bundeslade Jehovahs trugen, wie der Fremdling so der Eingeborene; die eine Hälfte gegenüber dem Berge Gerissim, und die andere Hälfte dem Berge Ebal gegenüber, wie Mose, der Knecht Jehovahs, zuerst geboten hatte, das Volk Israel zu segnen.',
        34: 'Und danach las er alle Worte des Gesetzes, den Segen und den Fluch, wie alles geschrieben ist im Buche des Gesetzes.',
        35: 'Da war kein Wort von allem, das Mose geboten hatte, das Joschua nicht las in Gegenwart der ganzen Versammlung Israels und den Weibern und Kindlein und dem Fremdling, der in ihrer Mitte wandelte.',
    },
    9: {
        1: 'Und es geschah, als dies hörten alle die Könige, die diesseits des Jordans auf dem Gebirge und in der Niederung und am ganzen Gestade des großen Meeres dem Libanon gegenüber wohnten, der Chethiter und der Amoriter, der Kanaaniter und der Pherisiter, der Chiviter und der Jebusiter;',
        2: 'Kamen sie zusammen zu Hauf, einmütig wider Joschua und Israel zu streiten.',
        3: 'Und die Einwohner Gibeons hörten, was Joschua mit Jericho und mit Ai getan hatte,',
        4: 'Da handelten sie auch mit List, gingen hin, machten sich eine Gesandtschaft und sie nahmen alte Säcke auf ihre Esel und alte, rissige und zusammengebundene Weinschläuche.',
        5: 'Und alte, geflickte Schuhe an ihre Füße und alte Gewänder an sich, und alles Brot ihrer Zehrung war vertrocknet und hatte Schimmelflecken.',
        6: 'Und sie gingen zu Joschua in das Lager zu Gilgal und sprachen zu ihm und zu den Männern von Israel: Wir kommen aus fernem Lande, und nun schließet einen Bund mit uns.',
        7: 'Und die Männer von Israel sprachen zu dem Chiviter: Vielleicht wohnst du mitten unter mir, und wie sollte ich einen Bund mit dir schließen?',
        8: 'Und sie sprachen zu Joschua: Wir sind deine Knechte. Und Joschua sprach zu ihnen: Wer seid ihr, und von wannen kommt ihr?',
        9: 'Und sie sagten zu ihm: Aus einem sehr fernen Lande kommen deine Knechte wegen des Namens Jehovahs, deines Gottes; denn wir hörten Sein Gerücht, und alles, was Er in Ägypten hat getan;',
        10: 'Und alles, was Er getan hat den zwei Königen des Amoriters jenseits des Jordans, dem Sichon, dem Könige von Cheschbon und Og, dem Könige von Baschan, der zu Aschtaroth war.',
        11: 'Und unsere Ältesten und alle, die in unserem Lande wohnen, sprachen zu uns und sagten: Nehmet Zehrung in eure Hand auf den Weg, und geht ihnen entgegen und sprechet zu ihnen: Wir sind eure Knechte, und nun schließet einen Bund mit uns.',
        12: 'Dies unser Brot nahmen wir warm als Zehrung aus unseren Häusern am Tage, da wir auszogen, zu euch zu gehen, und siehe, nun ist es vertrocknet und mit Schimmelflecken;',
        13: 'Und diese Weinschläuche füllten wir neu, und siehe, sie sind rissig geworden; und das sind unsere Gewänder und unsere Schuhe, sie sind von dem sehr vielen Wege alt geworden.',
        14: 'Und die Männer nahmen von ihrer Zehrung; aber den Mund Jehovahs fragten sie nicht.',
        15: 'Und Joschua machte Frieden mit ihnen und schloß einen Bund mit ihnen, sie am Leben zu lassen; und die Fürsten der Gemeinde schworen denselben.',
        16: 'Und es geschah am Ende dreier Tage, nachdem sie den Bund mit ihnen geschlossen hatten, da hörten sie, daß sie ihnen nahe wären und in ihrer Mitte wohnten.',
        17: 'Und die Söhne Israels brachen auf und kamen zu ihren Städten am dritten Tage; und ihre Städte waren Gibeon und Kephirah und Beeroth und Kirjath Jearim;',
        18: 'Und die Söhne Israels schlugen sie nicht, weil die Fürsten der Gemeinde ihnen bei Jehovah, dem Gotte Israels, geschworen hatten; und die ganze Gemeinde murrte wider die Fürsten.',
        19: 'Und alle die Fürsten sprachen zu der ganzen Gemeinde: Wir haben ihnen bei Jehovah, dem Gotte Israels, geschworen, und nun vermögen wir nicht sie anzurühren.',
        20: 'Das wollen wir ihnen tun, daß wir sie leben lassen, auf daß keine Entrüstung über uns sei um des Schwures willen, den wir ihnen geschworen haben.',
        21: 'Und die Fürsten sprachen zu ihnen: Sie sollen am Leben bleiben, aber Holzhauer und Wasserschöpfer für die ganze Gemeinde werden, wie die Fürsten zu ihnen geredet hatten.',
        22: 'Und Joschua rief sie und redete zu ihnen und sprach: Warum habt ihr uns betrogen und gesagt: Wir sind sehr ferne von euch, und ihr wohnet doch mitten unter uns?',
        23: 'Und nun seid ihr verflucht! Nicht sollen unter euch aufhören der Knecht und die Holz hauen und Wasser schöpfen für das Haus meines Gottes!',
        24: 'Und sie antworteten Joschua und sprachen: Man hatte deinen Knechten angesagt, was Jehovah, dein Gott, dem Mose, Seinem Knechte, geboten hat, daß er euch das ganze Land gebe, und daß ihr alle Einwohner des Landes vor euch her vernichten sollet. Darum fürchteten wir sehr für unsere Seelen vor euch, so daß wir dieses taten.',
        25: 'Und nun, siehe, wir sind in deiner Hand. Was gut und was recht ist in deinen Augen uns zu tun, das tue.',
        26: 'Und er tat ihnen also und errettete sie aus der Hand der Söhne Israels, daß sie sie nicht erwürgeten.',
        27: 'Und Joschua machte sie selbigen Tages zu Holzhauern und Wasserschöpfern für die Gemeinde und für den Altar Jehovahs bis auf diesen Tag, an dem Ort, den Er erwählen würde.',
    },
    10: {
        1: 'Und es geschah, da Adoni-Zedek, König von Jerusalem, hörte, daß Joschua Ai erobert und es verbannt hatte, wie er Jericho und ihrem Könige getan, also tat er mit Ai und seinem Könige, und daß die Einwohner Gibeons mit Israel Frieden gemacht hätten und in ihrer Mitte waren;',
        2: 'Da fürchteten sie sich sehr; denn Gibeon war eine große Stadt, wie eine der Königsstädte, und weil sie größer den Ai und alle ihre Männer Helden waren.',
        3: 'Und Adoni-Zedek, König von Jerusalem, sandte zu Hoham, König von Chebron, und zu Piram, König von Jarmuth, und zu Japhia, König von Lachisch und zu Debir, König von Eglon, und sagte:',
        4: 'Ziehet herauf zu mir und stehet mir bei, daß wir Gibeon schlagen, weil es Frieden mit Joschua und mit den Söhnen Israels gemacht.',
        5: 'Und sie sammelten sich und zogen herauf, fünf Könige der Amoriter, der König von Jerusalem, der König von Chebron, der König von Jarmuth, der König von Lachisch, der König von Eglon, sie und all ihre Lager, und sie lagerten sich wider Gibeon und stritten dawider.',
        6: 'Und die Männer Gibeons sandten zu Joschua zum Lager nach Gilgal, und ließen ihm sagen: Laß deine Hand nicht ab von deinen Knechten. Zieh eilig herauf zu uns, und hilf uns und stehe uns bei; denn es sind wider uns zusammengekommen alle Könige des Amoriters, die auf dem Gebirge wohnen.',
        7: 'Und Joschua zog herauf von Gilgal, er und alles Kriegsvolk mit ihm, und alle tapferen Helden.',
        8: 'Und Jehovah sprach zu Joschua: Fürchte dich nicht vor ihnen; denn Ich habe sie in deine Hände gegeben. Kein Mann von ihnen wird stehen vor dir.',
        9: 'Und Joschua kam plötzlich über sie; denn er war die ganze Nacht von Gilgal heraufgezogen.',
        10: 'Und Jehovah verwirrte sie vor Israel, und er schlug sie in einer großen Schlacht in Gibeon und setzte ihnen nach, den Weg der Steige von Beth-Choron hinan, und schlug sie bis nach Asekah und bis Makkedah.',
        11: 'Und es geschah, daß, als sie vor Israel flohen, da sie am Hinabsteigen von Beth-Choron waren, daß Jehovah große Steine vom Himmel auf sie warf, bis nach Asekah, daß sie starben. Mehr starben durch die Hagelsteine, als die Söhne Israels durch das Schwert erwürgt hatten.',
        12: 'Damals redete Joschua zu Jehovah, am Tage, da Jehovah die Amoriter hingab vor den Söhnen Israels, und sprach vor den Augen Israels: Sonne, sei still in Gibeon, und du, Mond im Talgrunde Ajalon!',
        13: 'Und die Sonne war stille, und der Mond stand, bis die Völkerschaft sich an den Feinden gerächt. Ist das nicht geschrieben in dem Buch Jaschar? Und es stand die Sonne an des Himmels Mitte und eilte nicht unterzugehen fast einen ganzen Tag.',
        14: 'Und vor ihm und nach ihm war kein solcher Tag, daß Jehovah auf eines Mannes Stimme hörte; denn Jehovah stritt für Israel.',
        15: 'Und Joschua und ganz Israel mit ihm kehrte zum Lager nach Gilgal zurück.',
        16: 'Und diese fünf Könige flohen und versteckten sich in der Höhle in Makkedah.',
        17: 'Und man sagte es dem Joschua an und sprach: Die fünf Könige sind gefunden, in der Höhle in Makkedah versteckt.',
        18: 'Und Joschua sprach: Wälzet große Steine an die Mündung der Höhle und bestellet Männer darüber, die ihrer hüten.',
        19: 'Ihr aber bleibt nicht stehen, setzet hinter euren Feinden nach, schlagt von ihnen die Hintersten und laßt sie nicht in ihre Städte eingehen; denn Jehovah, euer Gott, hat sie in eure Hand gegeben.',
        20: 'Und es geschah, als Joschua und die Söhne Israels vollendeten, und sie in der sehr großen Schlacht geschlagen hatten, bis sie alle wurden, und ein Rest von ihnen überblieb, und in die festen Städte gekommen war;',
        21: 'Da kehrte alles Volk im Frieden in das Lager zu Joschua nach Makkedah zurück. Und keiner durfte wider einen Mann der Söhne Israels die Zunge spitzen.',
        22: 'Und Joschua sprach: Öffnet die Mündung der Höhle und bringt diese fünf Könige zu mir heraus aus der Höhle.',
        23: 'Und sie taten so, und brachten zu ihm heraus aus der Höhle diese fünf Könige, den König von Jerusalem, den König von Chebron, den König von Jarmuth, den König von Lachisch, den König von Eglon.',
        24: 'Und es geschah, als man diese Könige zu Joschua herausgebracht hatte, da rief Joschua allen Männern von Israel und sprach zu den Anführern der Kriegsleute, die mit ihm gezogen: Nahet euch und setzet eure Füße auf die Hälse dieser Könige! Und sie nahten und setzten ihr Füße auf ihre Hälse.',
        25: 'Und Joschua sprach zu ihnen: Fürchtet euch nicht und entsetzet euch nicht, seid stark und rüstig; denn so wird Jehovah allen euren Feinden tun, mit denen ihr streitet.',
        26: 'Und Joschua schlug sie danach und tötete sie und hängte sie an fünf Bäume, und sie hingen an den Bäumen bis zum Abend.',
        27: 'Und es geschah zur Zeit, da die Sonne unterging, gebot Joschua, sie sollten sie von den Bäumen abnehmen, und sie warfen sie in die Höhle, in der sie sich versteckt hatten, und sie legten große Steine auf die Mündung der Höhle, bis auf diesen Tag.',
        28: 'Und Makkedah eroberte Joschua an demselben Tage und schlug sie und ihren König mit der Schärfe des Schwertes; er verbannte sie und jede Seele, die darin war, und ließ keinen Rest verbleiben; und dem Könige von Makkedah tat er, wie er dem Könige von Jericho getan.',
        29: 'Und Joschua und ganz Israel mit ihm zog hinüber von Makkedah gegen Libnah und er stritt wider Libnah.',
        30: 'Und Jehovah gab auch sie in die Hand Israels und ihren König, und er schlug sie mit der Schärfe des Schwertes, und jede Seele, die darin war; er ließ keinen Rest übrig, und tat ihrem Könige, wie er dem König von Jericho getan.',
        31: 'Und Joschua und ganz Israel mit ihm zog hinüber von Libnah nach Lachisch, und er lagerte wider dieselbe und stritt mit ihr.',
        32: 'Und Jehovah gab Lachisch in die Hand Israels, und es eroberte sie am zweiten Tag, und schlug sie mit der Schärfe des Schwertes und jede Seele darin, ganz so, wie er Libnah getan.',
        33: 'Damals zog Horam, König von Geser, herauf, um Lachisch beizustehen, aber Joschua schlug ihn und sein Volk, so daß er keinen Rest überließ.',
        34: 'Und Joschua zog hinüber und ganz Israel mit ihm, von Lachisch nach Eglon, und sie lagerten wider dieselbe und stritten mit ihr.',
        35: 'Und sie eroberten sie am selbigen Tage und schlugen sie mit der Schärfe des Schwertes; und alle Seele, die darin war, verbannte er an selbigem Tage, ganz so wie er mit Lachisch getan hatte.',
        36: 'Und von Eglon zog Joschua und ganz Israel mit ihm hinauf nach Chebron, und sie stritten mit ihr.',
        37: 'Und sie eroberten sie, und schlugen sie und ihren König und alle ihre Städte, und jede Seele, die darin war, mit der Schärfe des Schwertes; er ließ keinen Rest übrig, ganz so wie er Eglon getan hatte, und verbannte sie und jede Seele, die darin war.',
        38: 'Und Joschua und ganz Israel mit ihm kehrten zurück gen Debir und stritten mit ihr;',
        39: 'Und eroberte dasselbe und seinen König und alle seine Städte, und sie schlugen sie mit der Schärfe des Schwertes, und sie verbannten jede Seele, die darinnen war, und ließen keinen Rest übrig. Wie er Chebron getan, so tat er Debir und ihrem Könige, und so wie er an Libnah und ihrem Könige getan hatte.',
        40: 'Und Joschua schlug das ganze Land, das Gebirge und das Mittagland, und die Niederung und die Abhänge, und alle ihre Könige, er ließ keinen Rest übrig, und verbannte alles, was Odem hatte, wie Jehovah, der Gott Israels, geboten hatte.',
        41: 'Und Joschua schlug sie von Kadesch-Barnea bis Gazah und das ganze Land Goschen bis Gibeon.',
        42: 'Und alle diese Könige und ihr Land eroberte Joschua mit einem Mal; denn Jehovah, der Gott Israels, stritt für Israel.',
        43: 'Und Joschua und ganz Israel mit ihm kehrte zum Lager nach Gilgal zurück.',
    },
    11: {
        1: 'Und es geschah, da Jabin, der König von Chazor, es hörte, da sandte er an Jobab, den König von Madon und an den König von Schimron und an den König von Achschaph;',
        2: 'Und an die Könige, die von Mitternacht her auf dem Gebirge und auf dem Flachland gen Mittag von Kinneroth und in der Niederung und in Naphoth Dor vom Meere her waren;',
        3: 'An den Kanaaniter vom Aufgang her und vom Meere her und den Amoriter und den Chethiter und den Pherisiter und den Jebusiter in dem Gebirge und den Chiviter unter dem Chermon im Lande Mizpah.',
        4: 'Und diese zogen aus, und all ihre Lager mit ihnen, viel Volkes wie der Sand am Ufer des Meeres an Menge; und sehr viel Rosse und Streitwagen.',
        5: 'Und es taten sich zusammen alle diese Könige, und kamen und lagerten beisammen an den Wassern Merom, um mit Israel zu streiten.',
        6: 'Und Jehovah sprach zu Joschua: Fürchte dich nicht vor ihnen; denn morgen um diese Zeit gebe Ich sie alle erschlagen dahin vor Israel. Ihre Rosse sollst du lähmen und ihre Streitwagen im Feuer verbrennen.',
        7: 'Und Joschua und all das Kriegsvolk mit ihm kam plötzlich über sie an den Wassern Merom und fiel über sie her.',
        8: 'Und Jehovah gab sie in die Hand Israels; und sie schlugen sie und setzten ihnen nach bis Zidon, die große Stadt, und bis Misrephoth Majim und bis zur Talebene Mizpeh gegen Aufgang, und sie schlugen sie, bis ihnen kein Rest übrig war.',
        9: 'Und Joschua tat ihnen, wie ihm Jehovah gesagt hatte: Ihre Rosse lähmte er und verbrannte ihre Streitwagen im Feuer.',
        10: 'Und Joschua kehrte um in selbiger Zeit und eroberte Chazor, und schlug dessen König mit dem Schwert. Denn Chazor war vordem das Haupt aller dieser Königreiche.',
        11: 'Und jede Seele in ihr erschlugen sie mit der Schärfe des Schwertes und verbannten es, so daß nichts überblieb, in dem Odem war. Und Chazor verbrannte er mit Feuer.',
        12: 'Und Joschua eroberte alle Städte dieser Könige und all ihre Könige, und schlug sie mit der Schärfe des Schwertes und verbannte sie, wie Mose, der Knecht Jehovahs, geboten hatte.',
        13: 'Jedoch verbrannte Israel keine der Städte, die auf Anhöhen standen; nur Chazor allein verbrannte Joschua.',
        14: 'Und alle Beute dieser Städte und das Vieh nahmen die Söhne Israels als Raub für sich; nur die Menschen alle schlugen sie mit der Schärfe des Schwertes, bis sie sie vernichtet hatten. Nichts, das Odem hatte, ließen sie verbleiben.',
        15: 'Wie Jehovah Seinem Knechte Mose geboten hatte, also gebot Mose dem Joschua; und also tat Joschua, und in keinem Worte wich dieser von allem ab, was Jehovah dem Mose geboten hatte.',
        16: 'Und Joschua nahm dies ganze Land, das Gebirge und das ganze Mittagsland, und das ganze Land Goschen und die Niederung, und das Flachland, und das Gebirge Israel und seine Niederung.',
        17: 'Von dem kahlen Berge, der aufsteigt gen Seir, bis Baal Gad in der Talebene des Libanon unten am Berge Chermon; und alle ihre Könige eroberte er und schlug und tötete sie.',
        18: 'Viele Tage hatte Joschua Streit mit allen diesen Königen.',
        19: 'Es war keine Stadt, die mit den Söhnen Israels Frieden machte, außer den Chivitern, den Einwohnern Gibeons; sie nahmen alle im Streit.',
        20: 'Denn von Jehovah war es, daß sie ihr Herz bestärkten, im Streite Israel zu begegnen, um sie zu verbannen, auf daß ihnen keine Gnade widerführe, sondern sie vernichtet würden, wie Jehovah Mose geboten hatte.',
        21: 'Und Joschua kam in selbiger Zeit und rottete die Enakim aus vom Gebirge, von Chebron, von Debir, von Anab, und vom ganzen Gebirge Judah und vom ganzen Gebirge Israel; mit ihren Städten verbannte sie Joschua.',
        22: 'Und man ließ keine Enakim im Lande der Söhne Israels übrigbleiben. Nur in Gazah, in Gath und in Aschdod verblieben sie.',
        23: 'Und Joschua nahm das ganze Land gemäß allem, was Jehovah zu Mose geredet hatte, und Joschua gab es Israel zum Erbe, nach den Teilen in ihren Stämmen, und das Land rastete vom Streit.',
    },
    12: {
        1: 'Und dies sind die Könige des Landes, welche die Söhne Israels schlugen und deren Land sie eingenommen, jenseits des Jordans gegen Aufgang der Sonne vom Bache Arnon bis zum Berge Chermon, und das ganze Flachland gegen Aufgang;',
        2: 'Sichon, der Amoriterkönig, der in Cheschbon wohnte und herrschte vor Aroer am Ufer des Baches Arnon und der Mitte des Baches und über die Hälfte von Gilead bis zum Bache Jabbok, der Grenze der Söhne Ammons;',
        3: 'Und über das Flachland bis zum Meer Kinneroth gegen Aufgang und bis zum Meer des Flachlandes, dem Salzmeer, gegen Aufgang auf dem Wege nach Beth-Jeschimoth, und im Süden unten an den Abhängen des Pisgah;',
        4: 'Und die Grenze Ogs, des Königs von Baschan, der von den Riesen übrigblieb, und zu Aschtaroth und Edrei wohnte,',
        5: 'Und herrschte auf dem Berge Chermon und in Salchah und in ganz Baschan bis zur Grenze des Geschuriters und des Maachathiters, und über das halbe Gilead, zur Grenze Sichons, des Königs von Cheschbon.',
        6: 'Mose, der Knecht Jehovahs, und die Söhne Israels schlugen sie, und Mose, der Knecht Jehovahs, gab es als Erbbesitz dem Rubeniter und dem Gaditer und dem halben Stamm Menascheh.',
        7: 'Und dies sind die Könige des Landes, die Joschua schlug und die Söhne Israels diesseits des Jordans, dem Meere zu von Baal-Gad in der Talebene des Libanons und bis zum kahlen Berg, der aufsteigt gen Seir; und Joschua gab es den Stämmen Israels nach ihren Teilen zum Erbbesitz.',
        8: 'Auf dem Gebirge und in der Niederung und in dem Flachlande und an den Abhängen und in der Wüste und im Mittagsland; die Chethiter, die Amoriter und die Kanaaniter, die Pherisiter, die Chiviter und die Jebusiter:',
        9: 'Der König von Jericho einer; der König von Ai, das zur Seite von Beth-El ist, einer.',
        10: 'Der König von Jerusalem einer; der König von Chebron einer;',
        11: 'Der König von Jarmuth einer; der König von Lachisch einer;',
        12: 'Der König von Eglon einer; der König von Geser einer;',
        13: 'Der König von Debir einer; der König von Geder einer;',
        14: 'Der König von Chorma einer; der König von Arad einer;',
        15: 'Der König von Libnah einer; der König von Adullam einer;',
        16: 'Der König von Makkedah einer; der König von Bethel einer;',
        17: 'Der König von Tappuach einer; der König von Chepher einer;',
        18: 'Der König von Aphek einer; der König Laschscharon einer;',
        19: 'Der König von Madon einer; der König von Chazor einer;',
        20: 'Der König von Schimron-Meron einer; der König von Achschaph einer;',
        21: 'Der König von Taanach einer; der König von Megiddo einer;',
        22: 'Der König von Kedesch einer; der König von Jokneam am Karmel einer;',
        23: 'Der König von Dor zu Naphoth-Dor einer; der König von Gojim zu Gilgal einer;',
        24: 'Der König von Tirzah einer. Aller Könige sind es einunddreißig..',
    },
    13: {
        1: 'Und Joschua war alt und betagt; und Jehovah sprach zu ihm: Du bist alt und betagt, und vom Lande verbleibt noch sehr viel einzunehmen.',
        2: 'Das ist das verbleibende Land: alle Kreise der Philister und ganz Geschuri.',
        3: 'Von Schichor, welcher vor Ägypten ist, und bis zur Grenze von Ektron gegen Norden wird es dem Kanaaniter zugerechnet; fünf Philisterfürsten sind es: der Gassiter, der Aschdoditer, der Aschkeloniter, der Gathiter, der Ekroniter und der Aviter.',
        4: 'Vom Süden, das ganze Land des Kanaaniters und Mearah der Zidonier bis Aphekah bis an die Grenze der Amoriter.',
        5: 'Und das Land der Gibliter und der ganze Libanon gegen Aufgang der Sonne von Baal-Gad an unten am Berge Chermon, bis man nach Chamath kommt.',
        6: 'Alle, die auf dem Gebirge wohnen vom Libanon bis Misrephoth Maim, alle Zidonier werde Ich austreiben vor den Söhnen Israels. Nur verlose es Israel zum Erbe, wie Ich dir geboten habe.',
        7: 'Und nun teile dies Land zum Erbe den neun Stämmen und dem halben Stamm Menascheh.',
        8: 'Mit ihm hatte der Rubeniter und der Gaditer ihr Erbe genommen, das ihnen Mose gab jenseits des Jordans gegen Aufgang, wie Mose, der Knecht Gottes, ihnen gegeben hatte.',
        9: 'Von Aroer an, das am Ufer des Baches Arnon ist, und die Stadt in der Mitte des Baches, und die ganze Ebene Medebah bis Dibon.',
        10: 'Und alle Städte Sichons des Amoriter Königs, der in Cheschbon regierte, bis zur Grenze der Söhne Ammons.',
        11: 'Und Gilead und die Grenze der Geschuriter und Maachathiter und der ganze Berg Chermon und ganz Baschan bis Salchah.',
        12: 'Das ganze Königreich Ogs in Baschan, welcher in Aschtaroth und Edrei regierte. Er verblieb von dem Überreste der Riesen. Und Mose schlug sie und trieb sie aus.',
        13: 'Und die Geschuriter und die Maachathiter trieben die Söhne Israels nicht aus; und Geschur und Maachath wohnen bis auf diesen Tag inmitten Israels.',
        14: 'Nur dem Stamme Levi gab Er kein Erbe, die Feueropfer Jehovahs, des Gottes Israels, sind sein Erbe, wie Er zu ihm geredet hatte.',
        15: 'Und Mose gab dem Stamme der Söhne Ruben nach ihren Familien;',
        16: 'Und ihre Grenze war von Aroer, das am Ufer des Baches Arnon ist, und die Stadt, die in der Mitte des Baches ist, und die ganze Ebene bei Medebah.',
        17: 'Cheschbon und alle seine Städte, die in der Ebene sind, Dibon und Bamoth-Baal und Beth-Baal- Meon.',
        18: 'Und Jahzah und Kedemoth und Mephaath;',
        19: 'Und Kirjathajim und Sibmah und ZerethHaschachar auf dem Berge des Talgrundes;',
        20: 'Und Beth-Peor und die Abhänge des Pisgah, und Beth Hajeschimoth;',
        21: 'Und alle Städte der Ebene und das ganze Königreich Sichons, des Amoriterkönigs, der in Cheschbon regierte, den Mose schlug, und die Fürsten Midians Evi und Rekem und Zur und Chur und Reba, die Gesalbten Sichons, die im Lande wohnten;',
        22: 'Und Bileam, den Sohn Beors, den Wahrsager, erwürgten die Söhne Israels mit dem Schwert, samt den Erschlagenen;',
        23: 'Und es war die Grenze der Söhne Rubens der Jordan und die Grenze. Dies ist das Erbe der Söhne Rubens nach ihren Familien, die Städte und ihre Dörfer.',
        24: 'Und Mose gab dem Stamme Gad, den Söhnen Gads, nach ihren Familien:',
        25: 'Und ihre Grenze war Jaeser und alle Städte Gileads und die Hälfte des Landes der Söhne Ammons bis Aroer, welches vor Rabbah ist;',
        26: 'Und von Cheschbon bis Ramath-Mizpeh und Betonim, und von Machanajim bis an die Grenze von Debir.',
        27: 'Und im Talgrunde Beth-Haram und Beth-Nimrah und Sukkoth und Zaphon, das übrige vom Königreiche des Sichon, des Königs von Cheschbon, war der Jordan die Grenze bis an das Ende des Meeres Kinneroth über dem Jordan nach dem Aufgang.',
        28: 'Dies ist das Erbe der Söhne Gads nach ihren Familien, die Städte und ihre Dörfer.',
        29: 'Und Mose gab dem halben Stamme Menascheh, und der halbe Stamm der Söhne Menascheh sollte nach ihren Familien haben.',
        30: 'Als Grenze von Machanajim an ganz Baschan, das ganze Königreich Ogs, des Königs von Baschan, und alle Flecken Jairs, die in Baschan waren, sechzig Städte;',
        31: 'Und das halbe Gilead und Aschtaroth und Edrei, die Städte in dem Königreiche Ogs in Baschan, den Söhnen Machirs, des Sohnes von Menascheh, der Hälfte der Söhne Machirs, nach ihren Familien.',
        32: 'Dies ist es, was Mose in dem Flachlande Moabs jenseits des Jordans gegen Aufgang von Jericho als Erbe verteilte.',
        33: 'Und dem Stamm Levi gab Mose kein Erbe. Jehovah, der Gott Israels, ist ihr Erbe, wie Er zu ihnen geredet hat.',
    },
    14: {
        1: 'Und dies ist, was die Söhne Israels im Lande Kanaan als Erbe erhielten, das ihnen zum Erbe verteilten Eleasar, der Priester, und Joschua, der Sohn Nuns, und die Häupter der Väter der Stämme, der Söhne Israels.',
        2: 'Durch das Los, wie Jehovah durch Mose geboten hatte, verteilten sie das Erbe den neun Stämmen und dem halben Stamm.',
        3: 'Denn Mose hatte den zwei Stämmen und dem halben Stamm das Erbe jenseits des Jordans gegeben, und den Leviten gab er kein Erbe in ihrer Mitte.',
        4: 'Denn die Söhne Josephs wurden zwei Stämme: Menascheh und Ephraim; und den Leviten gaben sie keinen Teil im Lande, sondern Städte zum Wohnen und deren Weichbilde für ihre Viehherden und ihren Besitz.',
        5: 'Wie Jehovah Mose geboten hatte, so taten die Söhne Israels und verteilten das Land.',
        6: 'Und die Söhne Judahs traten herzu zu Joschua in Gilgal; und Kaleb, der Sohn Jephunnehs, der Kenissite, sprach zu ihm: Du weißt das Wort, das Jehovah zu Mose, dem Manne Gottes, in Kadesch Barnea meinetwegen und deinetwegen geredet hat.',
        7: 'Vierzig Jahre war ich alt, als Mose der Knecht Jehovahs, mich aus Kadesch Barnea sandte, das Land auszukundschaften, und ich brachte ihm Nachricht zurück, wie es in meinem Herzen war.',
        8: 'Aber meine Brüder, die mit mir hinaufgezogen waren, machten das Herz des Volkes zerschmelzen; ich aber folgte Jehovah, meinem Gotte, völlig.',
        9: 'Und Mose schwur selbigen Tages und sprach: Fürwahr, das Land, das dein Fuß betreten hat, soll dir und deinen Söhnen zum Erbe sein ewiglich; denn du folgtest Jehovah, meinem Gotte, völlig.',
        10: 'Und nun siehe, Jehovah hat mich am Leben erhalten, wie Er geredet hat, diese fünfundvierzig Jahre, seit Jehovah dies Wort geredet hat zu Mose, da Israel in der Wüste zog, und nun siehe, ich bin diesen Tag fünfundachtzig Jahre alt.',
        11: 'Noch bin ich diesen Tag so stark, wie am Tage, da Mose mich sandte; wie meine Kraft war damals, so ist meine Kraft jetzt, zum Streit, zum Ausgang und zum Eingang.',
        12: 'Und nun, gib mir diesen Berg, davon Jehovah an selbigem Tag geredet hat. Denn du hast an demselben Tage gehört, daß Enakim dort sind, und große, feste Städte. Vielleicht ist Jehovah mit mir, daß ich sie austreibe, wie Jehovah geredet hat.',
        13: 'Und Joschua segnete ihn und gab Chebron dem Kaleb, dem Sohne Jephunnehs, zum Erbe.',
        14: 'Deshalb ward Chebron dem Kaleb, dem Sohne Jephunnehs, dem Kenissiten zum Erbe bis auf diesen Tag, darum, daß er Jehovah, dem Gotte Israels, völlig gefolgt.',
        15: 'Und der Name Chebron war vordem Kirjath Arbah, eines Menschen, der groß war unter den Enakim; und das Land rastete vom Krieg.',
    },
    15: {
        1: 'Und das Los für den Stamm der Söhne Judahs nach ihren Familien war an der Grenze Edoms, die Wüste Zin, gegen Mittag am südlichen Ende.',
        2: 'Und ihre Mittagsgrenze war vom Ende des Salzmeeres an, von der Zunge, die sich gegen Mittag wendet.',
        3: 'Und ging hinaus mittäglich von Maaleh Akrabbim und ging hinüber nach Zin und stieg mittäglich von Kadesch Barnea auf, und ging hinüber nach Chezron und stieg auf nach Addar und wandte sich nach Karka um.',
        4: 'Und ging hinüber nach Azmon und ging aus am Bache Ägyptens, und die Ausläufe der Grenze waren nach dem Meere hin. Dies soll eure Mittagsgrenze sein.',
        5: 'Und die Grenze nach Osten ist das Salzmeer bis an das Ende des Jordans. Und die Grenze nach der Seite gegen Mitternacht ist von der Meereszunge an vom Ende des Jordans.',
        6: 'Und die Grenze steigt auf nach Beth-Choglah, und geht hinüber von Mitternacht nach Beth-Arabah, und die Grenze steigt auf nach dem Stein Bohans, des Sohnes Rubens.',
        7: 'Und die Grenze steigt auf gen Debir vom Talgrunde Achor, und Mitternacht zu wendet sie sich gen Gilgal, der Maaleh Adummim stracks gegenüber, welches auf der Mittagseite des Baches liegt. Und die Grenze geht hinüber zu den Wassern von En-Schemesch, und seine Ausläufe gehen bis En-Rogel.',
        8: 'Und die Grenze steigt auf nach der Schlucht Ben Hinnom auf der Mittagseite des Jebusiters, das ist von Jerusalem, und von da steigt die Grenze auf die Spitze des Berges, der vor Ge Hinnom ist, dem Meere zu, am Ende des Talgrundes Rephaim gegen Mitternacht.',
        9: 'Und vom Gipfel des Berges erstreckt sich die Grenze hin nach dem Brunnquell der Wasser von Nephthoach und geht aus nach den Städten des Berges Ephron und die Grenze erstreckt sich nach Baalah, das ist Kirjath Jearim.',
        10: 'Und die Grenze wendet sich herum von Baalah nach dem Meere zum Berge Seir und geht hinüber an die Mitternachtseite des Jearimgebirges, das ist Chesalon, und geht hinab nach Beth-Schemesch und geht hinüber nach Timnah.',
        11: 'Und die Grenze geht aus nach der Mitternachtseite von Ekron; und die Grenze erstreckte sich nach Schikkeron und geht hinüber nach dem Berg von Baalah und geht aus nach Jabneel, und die Ausläufe der Grenze sind dem Meere zu.',
        12: 'Und die Meeresgrenze ist am großen Meer und seiner Grenze. Dies ist die Grenze der Söhne Judah ringsum nach ihren Familien.',
        13: 'Und dem Kaleb, dem Sohne Jephunnehs, gab man nach Jehovahs Befehl an Joschua als Teil inmitten der Söhne Judahs Kirjath Arbah des Vaters des Enak, das ist Chebron.',
        14: 'Und Kaleb trieb aus von da die drei Söhne Enaks, Scheschai und Achiman und Thalmai, die Enakskinder.',
        15: 'Und von dannen zog er hinauf gegen die Einwohner Debirs, und der Name Debirs war vordem Kirjath Sepher.',
        16: 'Und Kaleb sprach: Wer Kirjath Sepher schlägt und es erobert, dem gebe ich meine Tochter Achsah zum Weibe.',
        17: 'Und Othniel, Sohn von Kenas, Kalebs Bruder, eroberte sie, und er gab ihm seine Tochter Achsah zum Weib.',
        18: 'Und es geschah, als sie einzog, trieb sie ihn an, von ihrem Vater Feld zu erbitten; und sie ließ sich vom Esel herab und Kaleb sprach zu ihr: Was ist dir?',
        19: 'Und sie sprach: Gib mir einen Segen; du hast mir ein Mittagsland gegeben, so gib mir auch Wasser. Und er gab ihr die oberen Wasserquellen und die unteren Wasserquellen.',
        20: 'Dies ist das Erbe des Stammes der Söhne Judahs nach seinen Familien.',
        21: 'Und es waren die Städte vom Ende des Stammes der Söhne Judahs an der Grenze Edoms gen Mittag: Kabzeel und Eder und Jagur.',
        22: 'Und Kinah und Dimonah und Adadah.',
        23: 'Und Kadesch und Chazor und Jithnan.',
        24: 'Siph und Telem und Bealoth.',
        25: 'Und Chazor, Chadathah und Kerijoth, Chezron, das ist Chazor.',
        26: 'Amam und Schema und Moladah.',
        27: 'Und Chazar-Gaddah und Cheschmon und Beth Pelet.',
        28: 'Und Chazar Schual und Beerschabah und Bisjothjah.',
        29: 'Baalah und Ijim und Ezem.',
        30: 'Und Eltholad und Chesil und Chormah.',
        31: 'Und Ziklag und Madmannah und Sansannah.',
        32: 'Und Lebaoth und Schilchim und Ain und Rimmon, im ganzen neunundzwanzig Städte und ihre Dörfer.',
        33: 'In der Niederung Eschthaol und Zorah und Aschnah.',
        34: 'Und Sanoach, und En-Gannim, Tappuach und Enam.',
        35: 'Jarmuth und Adullam, Sochoh und Asekah.',
        36: 'Und Schaarajim und Adithaim und Gederah und Gederothajim, vierzehn Städte und ihre Dörfer.',
        37: 'Zenan und Chadaschah und Migdal-Gad.',
        38: 'Und Dilean, Mizpeh und Joktheel;',
        39: 'Lachisch und Bozkath und Eglon;',
        40: 'Und Chabbon und Lachmas und Kithlisch;',
        41: 'Und Gederoth, Beth-Dagon und Naamah und Makkedah; sechzehn Städte und ihre Dörfer;',
        42: 'Libnah und Ether und Aschan;',
        43: 'Und Jiphtach und Aschnah und Nezib;',
        44: 'Kegilah und Achsib und Mareschah; neun Städte und ihre Dörfer.',
        45: 'Ekron und ihre Töchterstädte und ihre Dörfer;',
        46: 'Von Ekron ab und dem Meere zu alles, was zur Seite von Aschdod ist, und ihre Dörfer;',
        47: 'Aschdod, seine Töchterstädte und seine Dörfer, Gassah, seine Töchterstädte und seine Dörfer; bis an den Bach Ägyptens und an das große Meer und seine Grenze.',
        48: 'Und auf dem Gebirge Schamir und Jathir und Sochoh;',
        49: 'Und Dannah und Kirjath-Sannah, das ist Debir.',
        50: 'Und Anab, Eschthemoh und Anim;',
        51: 'Und Goschen und Cholon und Giloh, elf Städte und ihre Dörfer;',
        52: 'Arab und Dumah und Eschan;',
        53: 'Und Janum und Beth-Tappuach und Aphekah;',
        54: 'Und Chummetah und Kirjath-Arbah, das ist Chebron, und Zior, neun Städte und ihre Dörfer;',
        55: 'Maon, Karmel und Siph und Jutah;',
        56: 'Und Jisreel und Jokdeam und Sanoach;',
        57: 'Kajin, Gibeah und Timnah, zehn Städte und ihre Dörfer;',
        58: 'Chalchul, Beth-Zur und Gedor.',
        59: 'Und Maarath und Beth und Anoth und Elthekon, sechs Städte und ihre Dörfer;',
        60: 'Kirjath Baal das ist Kirjath Jearim und Rabbah, zwei Städte und ihre Dörfer;',
        61: 'In der Wüste Beth-Arabah, Middin und Sechachah;',
        62: 'Und Nibschan und Ir-Hammelach und En-Gedi, sechs Städte und ihre Dörfer.',
        63: 'Und die Jebusiter, die in Jerusalem wohnen, vermochten die Söhne Judahs nicht auszutreiben; und der Jebusiter wohnt mit den Söhnen Judahs in Jerusalem bis auf diesen Tag.',
    },
    16: {
        1: 'Und für die Söhne Josephs kam heraus das Los vom Jordan bei Jericho an die Wasser von Jericho gegen Aufgang; die Wüste hinaufsteigend von Jericho in das Gebirge nach Bethel.',
        2: 'Und sie ging aus von Bethel gen Lus und zog sich hinüber nach der Grenze des Architers nach Ataroth;',
        3: 'Und ging hinab dem Meere zu an die Grenze des Japhletiters bis zur Grenze des unteren Beth-Chorons und bis nach Geser, und seine Ausläufe waren an das Meer.',
        4: 'Und die Söhne Josephs erhielten es als Erbe, Menascheh und Ephraim.',
        5: 'Und die Grenze der Söhne Ephraims nach ihren Familien war: die Grenze ihres Erbes war aber gegen den Aufgang von Atroth-Addar bis gegen das obere Beth-Choron.',
        6: 'Und die Grenze ging hinaus nach dem Meere, gen Michmethath nördlich; und die Grenze wandte sich herum nach dem Aufgang bis Thaanath-Schiloh und zog sich hinüber vom Aufgang gen Janochah;',
        7: 'Und ging hinab von Janochah nach Ataroth und Naarath und stieß an Jericho und ging aus an den Jordan.',
        8: 'Von Tappuach ging die Grenze dem Meere zu gen Nachal Kanah. Und ihre Ausläufe waren an das Meer. Dies ist das Erbe des Stammes der Söhne Ephraims nach ihren Familien.',
        9: 'Und die den Söhnen Ephraims ausgeschiedenen Städte waren inmitten des Erbes der Söhne Menaschehs, alle Städte und ihre Dörfer.',
        10: 'Sie trieben aber die Kanaaniter, die in Geser wohnten, nicht aus; und der Kanaaniter wohnt mitten unter Ephraim bis auf diesen Tag und wurde zum zinsbaren Knechte.',
    },
    17: {
        1: 'Und es ward ein Los dem Stamme Menaschehs, denn er war der Erstgeborene Josephs: an Machir, den Erstgeborenen Menaschehs, den Vater des Gilead; denn er war ein Kriegsmann, und es ward ihm Gilead und Baschan.',
        2: 'Und die übrigen Söhne Menaschehs nach ihren Familien: an die Söhne Abiesers und an die Söhne Cheleks und an die Söhne Asriels und an die Söhne Schechems und an die Söhne Chephers und an die Söhne Schemidas. Dies sind die Söhne Menaschehs, des Sohnes Josephs, die männlichen nach ihren Familien.',
        3: 'Und Zelophchad, der Sohn Chephers ein Sohn Gileads, des Sohnes Machirs, des Sohnes Menaschehs, hatte keine Söhne, sondern nur Töchter. Und dies sind die Namen seiner Töchter: Machlah und Noah, Choglah, Milkah und Thirzah.',
        4: 'Und sie nahten vor Eleasar, den Priester, und vor Joschua, den Sohn Nuns, und die Fürsten und sprachen: Jehovah hat dem Mose geboten, uns ein Erbe inmitten unserer Brüder zu geben; und er gab ihnen nach dem Munde Jehovahs ein Erbe in der Mitte der Brüder ihres Vaters.',
        5: 'Und es fielen auf Menascheh zehn Erbteile, außer dem Lande Gilead und Baschan, jenseits des Jordans.',
        6: 'Denn die Töchter Menaschehs erbten ein Erbe in der Mitte seiner Söhne, und das Land Gilead ward den übrigen Söhnen Menaschehs.',
        7: 'Und es war die Grenze Menaschehs von Ascher bis Michmethath, welches vor Schechem ist, und es ging die Grenze zur Rechten zu den Einwohnern von En-Tappuach;',
        8: 'Dem Menascheh ward das Land Tappuach; aber Tappuach an der Grenze Menaschehs ward den Söhnen Ephraims. Jos.16/8f.',
        9: 'Und die Grenze ging hinab an Nachal Kanah auf der Mittagseite von dem Bache. Diese Städte sind Ephraims in der Mitte der Städte Menaschehs. Und die Grenze Menaschehs war nördlich vom Bache; und ihre Ausläufe waren an das Meer.',
        10: 'Nach Mittag war es des Ephraim und nach Norden des Menascheh, und das Meer war seine Grenze; und an Ascher stießen sie gegen Mitternacht und gegen Aufgang an Issaschar.',
        11: 'Und des Menascheh waren in Issaschar und in Ascher: Beth-Schean und ihre Töchter- städte, und Jibleam und ihre Töchterstädte, und die Einwohner von Dor und ihre Töchterstädte, und die Einwohner von Endor und deren Töchterstädte, und die Einwohner von Thaanach und ihre Töchterstädte, und die Einwohner von Megiddo und ihre Töchterstädte, drei Landstriche.',
        12: 'Und die Söhne Menaschehs vermochten nicht diese Städte einzunehmen und ließen den Kanaaniter im Lande wohnen.',
        13: 'Und es geschah, als die Söhne Israels stärker wurden, machten sie sich den Kanaaniter zinsbar, trieben ihn aber nicht aus.',
        14: 'Und die Söhne Josephs redeten zu Joschua und sagten: Warum hast du mir nur ein Los und einen Erbteil zum Erbe gegeben, und ich habe viel Volks, sintemal Jehovah mich so gesegnet hat?',
        15: 'Und Joschua sprach zu ihnen: Wenn du viel Volk hast, so zieh hinauf in den Wald und haue ihn dir dort nieder, im Lande der Pherisiter und der Rephaim, so euch zu eng ist das Gebirge Ephraim!',
        16: 'Und die Söhne Josephs sprachen: Den Berg werden wir nicht erlangen, und alle Kanaaniter, die in dem Lande des Talgrundes wohnen, die in Beth-Schean und ihren Töchterstädten und die im Tale Jesreel haben eiserne Streitwagen.',
        17: 'Und Joschua sprach zu dem Hause Joseph, zu Ephraim und Menascheh und sagte: Viel Volks hast du und hast große Kraft. Du sollst nicht ein Los haben;',
        18: 'Sondern einen Berg sollst du haben, da Wald ist, und so du ihn niederhaust, sollen seine Ausläufe dein sein, denn du wirst den Kanaaniter austreiben, so er auch eiserne Wagen hat, so stark ist er.',
    },
    18: {
        1: 'Und es versammelte sich die ganze Gemeinde der Söhne Israels in Schiloh und richteten daselbst das Versammlungszelt auf; denn das Land war vor ihnen unterworfen.',
        2: 'Und es waren noch sieben Stämme unter den Söhnen Israels übrig, denen noch nicht ein Erbe verteilt war.',
        3: 'Und Joschua sprach zu den Söhnen Israels: Wie lange wollt ihr lässig sein, hinzugehen und das Land einzunehmen, das Jehovah, der Gott eurer Väter, euch gegeben hat?',
        4: 'Gebet her für euch von je einem Stamm drei Männer, daß ich sie sende und sie sich aufmachen und im Land umhergehen und es beschreiben zum Behuf ihres Erbes und kommen zu mir.',
        5: 'Und ihr sollt es in sieben Teile teilen. Judah bleibe im Mittagsland in seinen Grenzen stehen, und das Haus Joseph bleibe auf seinen Grenzen im Norden stehen!',
        6: 'Und ihr sollt das Land in sieben Teile schreiben, und es zu mir hierher bringen, auf daß ich euch hier vor Jehovah, unserem Gott, das Los werfe.',
        7: 'Denn keinen Teil haben in eurer Mitte die Leviten; denn das Priestertum Jehovahs ist ihr Erbe. Und Gad und Ruben und der halbe Stamm Menaschehs haben jenseits des Jordans gegen den Aufgang ihr Erbe, das ihnen Mose, der Knecht Jehovahs, gegeben hat, genommen.',
        8: 'Und die Männer machten sich auf und gingen. Und Joschua gebot denen, die gingen, das Land zu beschreiben und sprach: Gehet hin und durchwandelt das Land und beschreibt es und kommt zu mir zurück, auf daß ich hier vor Jehovah in Schiloh das Los für euch werfe.',
        9: 'Und die Männer gingen und durchzogen das Land und beschrieben es nach den Städten zu sieben Teilen in ein Buch und kamen zu Joschua in das Lager nach Schiloh.',
        10: 'Und Joschua warf für sie das Los in Schiloh vor Jehovah, und Joschua verteilte allda das Land den Söhnen Israels nach ihren Teilen.',
        11: 'Und herauf kam das Los des Stammes der Söhne Benjamins nach seinen Familien. Und die Grenze ihres Loses kam heraus zwischen den Söhnen Judahs und den Söhnen Josephs.',
        12: 'Und ihre Grenze war an der Nordecke am Jordan, und die Grenze stieg auf hinter auf der Nordseite und ging hinauf auf den Berg gegen das Meer, und ihre Ausläufe waren nach der Wüste Beth Aven.',
        13: 'Und von dannen ging die Grenze hinüber nach Lus, an die Mittagseite von Lus, das ist Bethel, und die Grenze geht hinab nach Atroth Addar auf den Berg, der an der Mittagseite des unteren Beth-Chorons ist.',
        14: 'Und die Grenze erstreckte sich und wendete sich herum zur Westseite mittäglich von dem Berge, der gegen Mittag vor Beth-Choron liegt, und seine Ausläufe waren bis Kirjath-Baal, das ist Kirjath-Jearim, eine Stadt der Söhne Judahs. Dies ist die Westseite.',
        15: 'Und die Mittagsecke ist vom Ende von Kirjath-Jearim, und die Grenze ging aus meerwärts, und ging aus nach dem Brunnquell der Wasser des Nephtoach.',
        16: 'Und die Grenze ging hinab nach dem Ende des Berges, der vor der Schlucht Ben-Hinnoms, die im Talgrunde Rephaim gegen Mitternacht ist, und ging hinab in die Schlucht Hinnoms zur Mittagseite des Jebusiters und ging hinab bis En Rogel;',
        17: 'Und erstreckte sich von Mitternacht und ging hinaus nach En Schemesch und ging aus nach Geliloth, das der Steige Adummim gerade gegenüber, und geht hinab zum Stein Bohans, des Sohnes Rubens;',
        18: 'Und sie zog hinüber an die Seite der Arabah gegen Mitternacht und ging hinab nach der Arabah;',
        19: 'Und die Grenze ging hinüber nach dem Rücken von Beth-Choglah gegen Mitternacht, und waren seine Ausläufe, die Grenze nach der Zunge des Salzmeeres gegen Mitternacht an dem mittäglichen Ende des Jordans. Das ist die Grenze gegen Mittag.',
        20: 'Und der Jordan begrenzt es auf der Ostseite. Das ist das Erbe der Söhne Benjamins nach ihren Grenzen ringsum nach ihren Familien.',
        21: 'Und die Städte des Stammes der Söhne Benjamins nach ihren Familien waren Jericho und Beth-Chogla und Emik Geziz.',
        22: 'Und Beth-Arabah und Zemarajim und Bethel.',
        23: 'Und Avim und Parah und Ophrah.',
        24: 'Und Chephar Ammonai und Ophni und Geba, zwölf Städte und ihre Dörfer;',
        25: 'Gibeon und Ramah und Beeroth.',
        26: 'Und Mizpeh und Chephirah und Mozah.',
        27: 'Und Rekem und Jirpeel und Tharalah.',
        28: 'Und Zela, Eleph und Jebusi, das ist Jerusalem, Gibath, Kirjath, vierzehn Städte und ihre Dörfer. Das ist das Erbe der Söhne Benjamins nach ihren Familien.',
    },
    19: {
        1: 'Und das zweite Los kam heraus für Schimeon, für den Stamm der Söhne Schimeons nach ihren Familien; und ihr Erbe war inmitten des Erbes der Söhne Judahs.',
        2: 'Und für sie waren in ihrem Erbe: Beer-Schaba und Scheba und Moladah;',
        3: 'Und Chazar-Schual und Balah und Ezem;',
        4: 'Und Eltholad und Bethul und Chormah;',
        5: 'Und Ziklag und Beth Marchaboth und Chazar Susah;',
        6: 'Und Beth-Lebaoth und Scharuchen, dreizehn Städte und ihre Dörfer;',
        7: 'Ain, Rimmon und Ether und Aschan, vier Städte und ihre Dörfer;',
        8: 'Und alle Dörfer, die rings um diese Städte waren bis Baalath-Beer, Ramath-Negeb. Dies das Erbe des Stammes der Söhne Schimeons nach ihren Familien.',
        9: 'Von dem Erbteil der Söhne Judahs ward das Erbe der Söhne Schimeons; denn der Teil der Söhne Judahs war zu viel für sie und die Söhne Schimeons erbten in der Mitte ihres Erbes.',
        10: 'Und das dritte Los stieg auf für die Söhne Sebuluns nach ihren Familien und die Grenze ihres Erbes war bis Sarid;',
        11: 'Und ihre Grenze ging hinauf gegen das Meer und Maralah und stieß an den Bach vor Jokneam.',
        12: 'Und von Sarid wendete es sich herum nach Osten, nach dem Aufgang der Sonne nach der Grenze von Chisloth-Thabor und ging hinaus nach Dabrath und ging hinauf nach Japhia.',
        13: 'Und von da ging sie hinüber nach Osten nach dem Aufgang gen Gath-Chepher, gen Itha-Kazin und ging aus nach Rimmon- Methoar, Neah;',
        14: 'Und die Grenze wandte sich um dieses nördlich nach Channathon, und ihre Ausläufe waren in der Schlucht Jiphtach-El.',
        15: 'Und Kattath und Nahalal und Schimron und Jidalah und Bethlechem, zwölf Städte und ihre Dörfer.',
        16: 'Dies ist das Erbe der Söhne Sebuluns nach ihren Familien: Diese Städte und ihre Dörfer.',
        17: 'Für Issaschar kam das vierte Los heraus, für die Söhne Issaschars nach ihren Familien.',
        18: 'Und ihre Grenze war: Jisreel, Chessulloth und Schunem.',
        19: 'Und Chapharajim und Schion und Anacharath;',
        20: 'Und Rabbith und Kischjon und Ebez;',
        21: 'Und Remeth und En-Gannim und En-Chaddah und Beth-Pazzez;',
        22: 'Und stieß die Grenze an Thabor und Schachazimah und Beth-Schemesch, und waren die Ausläufe ihrer Grenze am Jordan. Sechzehn Städte und ihre Dörfer.',
        23: 'Das ist das Erbe des Stammes der Söhne Issaschars nach ihren Familien, die Städte und ihr Dörfer.',
        24: 'Und das fünfte Los kam heraus für den Stamm der Söhne Aschers nach ihren Familien.',
        25: 'Und ihre Grenze war: Chelkath und Chali und Beten und Achschaph.',
        26: 'Und Allammelech und Amad und Mischal; und dem Meere zu stieß sie an den Karmel und an Schichor-Libnath;',
        27: 'Und wandte sich zurück nach dem Aufgang der Sonne gen Beth-Dagon und stieß an Sebulun und an die Schlucht Jiphthach-El, nördlich von Beth-Emek und Negiel und ging hinaus nach Kabul zur Linken;',
        28: 'Und Ebron und Rechob und Chammon und Kanah bis Zidon, der großen;',
        29: 'Und die Grenze wandte sich zurück nach Ramah und bis zur Stadt Mizbar-Zor; und die Grenze wandte sich zurück nach Chosah, und ihre Ausläufe waren nach dem Meere hin vom Landstrich nach Achsib;',
        30: 'Und Ummah und Aphek und Rechob, zweiundzwanzig Städte und ihre Dörfer.',
        31: 'Dies ist das Erbe des Stammes der Söhne Aschers nach ihren Familien, diese Städte und ihre Dörfer.',
        32: 'Für die Söhne Naphthalis kam das sechste Los heraus, für die Söhne Naphthalis nach ihren Familien.',
        33: 'Und ihre Grenze war von Cheleph, von Elon in Zaanannim und Adami Nekeb und Jabneel bis Lakkum, und ihre Ausläufe waren an den Jordan.',
        34: 'Und die Grenze wandte sich zurück dem Meere zu nach Asnoth Thabor und ging von da aus nach Chukkok und stieß an Sebulun auf der Mittagseite und an Ascher stieß sie gegen das Meer, und am Jordan gegen Aufgang der Sonne an Judah.',
        35: 'Und feste Städte hatten sie: Ziddim, Zer und Chammath, Rakkath und Chinnereth.',
        36: 'Und Adamah und Ramah und Chazor.',
        37: 'Und Kedesch und Edrei und En-Chazor;',
        38: 'Und Jiron und Migdal-El, Chorem und Beth-Anath und Beth-Schemesch, neunzehn Städte und ihre Dörfer.',
        39: 'Dies ist das Erbe des Stammes der Söhne Naphthalis nach ihren Familien: die Städte und ihre Dörfer.',
        40: 'Für den Stamm der Söhne Dans nach ihren Familien kam heraus das siebente Los.',
        41: 'Und die Grenze ihres Erbes war: Zorah und Eschthaol und Ir-Schemesch;',
        42: 'Und Schaalabbin und Ajalon und Jithlah;',
        43: 'Und Elon und Timnatha und Ekron',
        44: 'Und Elthekeh und Gibbethon und Baa- lath.',
        45: 'Und Jehud und Bene-Barak, und Gath-Rimmon;',
        46: 'Und Me-Jarkon und Rakkon mit der Grenze gegen Japho.',
        47: 'Und die Grenze der Söhne Dans ging über sie hinaus, und die Söhne Dans zogen hinauf und stritten mit Leschem und eroberten sie und schlugen sie mit der Schärfe des Schwertes und nahmen sie ein und wohnten darin, und nannten Leschem Dan nach dem Namen ihres Vaters Dan.',
        48: 'Das ist das Erbe des Stammes der Söhne Dans nach ihren Familien, diese Städte und ihre Dörfer.',
        49: 'Und als sie die Erbverteilung des Landes nach seinen Grenzen vollendet hatten, da gaben die Söhne Israels Joschua, dem Sohne Nuns, ein Erbe in ihrer Mitte.',
        50: 'Nach dem Munde Jehovahs gaben sie ihm die Stadt, die er sich erbeten, Timnath-Serach, auf dem Gebirge Ephraim, und er baute die Stadt und wohnte darin.',
        51: 'Dies sind die Erbe, die Eleasar, der Priester, und Joschua, der Sohn Nuns, und die Häupter der Väter der Stämme der Söhne Israels in Schiloh vor Jehovah am Eingang des Versammlungszeltes durch das Los zum Erbe verteilten, und sie vollendeten die Verteilung des Landes.',
    },
    20: {
        1: 'Und Jehovah redete zu Joschua und sprach:',
        2: 'Rede zu den Söhnen Israels und sprich: Nehmet euch die Zufluchtsstätte, von denen Ich zu euch durch Moses Hand geredet habe.',
        3: 'Auf daß dahin fliehe der Totschläger, der eine Seele aus Versehen und ohne Wissen geschlagen hat; und sie sollen euch eine Zuflucht vor dem Bluträcher sein.',
        4: 'Und der da flieht zu einer von diesen Städten, soll stehen am Eingang des Tores der Stadt, und soll vor den Ohren der Ältesten dieser Stadt seine Worte reden, und sie sollen ihn zu sich in die Stadt nehmen und ihm einen Ort geben, daß er bei ihnen wohne.',
        5: 'Und so der Bluträcher ihm hinten nachsetzt, sollen sie den Totschläger nicht in seine Hand überantworten, weil er ohne Wissen seinen Genossen geschlagen hat, und hat ihn nicht seit gestern oder ehegestern gehaßt.',
        6: 'Und er wohne in selbiger Stadt, bis daß er vor der Gemeinde zu Gericht stehe, bis daß sterbe der Hohepriester, der in denselben Tagen sein wird. Alsdann darf der Totschläger in seine Stadt und in sein Haus zurückkehren, zur Stadt, aus der er geflohen ist.',
        7: 'Und sie heiligten Kedesch im Galil auf dem Gebirge Naphthali und Schechem auf dem Gebirge Ephraim und Kirjath-Arbah, das ist Chebron, auf dem Gebirge Judah.',
        8: 'Und jenseits des Jordans bei Jericho nach dem Aufgang zu, gaben sie Bezer in der Wüste in der Ebene vom Stamme Rubens, und Ramoth in Gilead vom Stamme Gad, und Golan in Baschan vom Stamm Menascheh.',
        9: 'Dies waren die Städte, bestimmt für alle Söhne Israels und den Fremdling, der sich in ihrer Mitte aufhält, auf daß dahin fliehe jeder, der aus Versehen eine Seele schlägt, auf daß er nicht durch die Hand des Bluträchers sterbe, bis daß er vor der Gemeinde gestanden ist.',
    },
    21: {
        1: 'Und es traten herzu die Häupter der Väter der Leviten zu Eleasar, dem Priester, und zu Joschua, dem Sohne Nuns, und zu den Häuptern der Stammväter der Söhne Israels;',
        2: 'Und redeten zu ihnen in Schiloh im Lande Kanaan und sprachen: Jehovah hat durch Moses Hand geboten, daß man uns Städte zum Wohnen und ihre Weichbilder für unser Vieh geben soll.',
        3: 'Und die Söhne Israels gaben den Leviten von ihrem Erbe, nach dem Ausspruch Jehovahs, diese Städte und ihre Weichbilder.',
        4: 'Und es kam heraus das Los für die Familien der Kohathiter, und es wurden den Söhnen Aharons, des Priesters, aus den Leviten, vom Stamme Judah und vom Stamme der Schimeoniter und vom Stamme Benjamin durch das Los dreizehn Städte;',
        5: 'Und den übrigen Söhnen Kohaths von den Familien des Stammes Ephraim und vom Stamme Dan und vom halben Stamm Menascheh durch das Los zehn Städte;',
        6: 'Und den Söhnen Gerschons von den Familien des Stammes Issaschar und von dem Stamme Ascher und von dem Stamme Naphthali und dem halben Stamm Menascheh und Baschan durch das Los dreizehn Städte;',
        7: 'Den Söhnen Meraris nach ihren Familien vom Stamme Ruben und vom Stamme Gad und vom Stamme Sebulun zwölf Städte.',
        8: 'So gaben durch das Los die Söhne Israels den Leviten diese Städte und ihre Weichbilder, wie Jehovah durch die Hand Moses geboten hatte.',
        9: 'Und aus dem Stamme der Söhne Judahs und aus dem Stamme der Söhne Schimeons gaben sie diese Städte, die mit Namen genannt sind.',
        10: 'Und sie wurden den Söhnen Aharons von den Familien der Kohathiter, von den Söhnen Levis, denn ihnen ward das Los zuerst.',
        11: 'Und sie gaben ihnen Kirjath Arbahs, des Vaters von Anok, das ist Chebron, auf dem Gebirge Judah und sein Weichbild rings um sie her.',
        12: 'Aber das Feld der Stadt und ihre Dörfer gaben sie Kaleb, dem Sohn Jephunnehs als Eigentum.',
        13: 'Und den Söhnen Aharons, des Priesters, gaben sie die Zufluchtsstadt für den Totschläger, Chebron und ihr Weichbild,',
        14: 'Und Jathir und ihr Weichbild und Eschthemoa und ihr Weichbild.',
        15: 'Und Cholon und ihr Weichbild und Debir und ihr Weichbild.',
        16: 'Und Ajin und ihr Weichbild, und Juttah und ihr Weichbild, und Beth Schemesch und ihr Weichbild, und neun Städte von diesen zwei Stämmen.',
        17: 'Und vom Stamme Benjamin Gibeon und ihr Weichbild, und Gebah und ihr Weichbild,',
        18: 'Und Anathoth und ihr Weichbild und Almon und ihr Weichbild, vier Städte.',
        19: 'Alle Städte der Söhne Aharons, des Priesters, waren dreizehn Städte und ihre Weichbilder.',
        20: 'Und den übrigen Familien der Söhne Kohaths, der Leviten von den Söhnen Kohaths, wurden Städte ihres Loses vom Stamme Ephraim.',
        21: 'Und sie gaben ihnen die Zufluchtsstadt für den Totschläger: Sichem und dessen Weichbild auf dem Gebirge Ephraim und Geser und ihr Weichbild,',
        22: 'Und Kibzajim und ihr Weichbild und Beth-Choron und ihr Weichbild, vier Städte;',
        23: 'Und vom Stamme Dan: Eltheke und ihr Weichbild und Gibbethon und ihr Weichbild,',
        24: 'Ajjalon und ihr Weichbild, Gath-Rimmon und ihr Weichbild, vier Städte.',
        25: 'Und von der Hälfte des Stammes Menascheh Thaanach und ihr Weichbild, zwei Städte.',
        26: 'Aller Städte waren es zehn mit ihren Weichbildern für die Familien der Söhne Kohaths, die noch übrig waren.',
        27: 'Und den Söhnen Gerschons von den Familien der Leviten gab man vom halben Stamm Menascheh die Zufluchtsstadt des Totschlägers: Golan in Baschan und ihr Weichbild, und Beeschtherah und ihr Weichbild, zwei Städte.',
        28: 'Und vom Stamme Issaschar Kischjon und ihr Weichbild, Dobrath und ihr Weichbild,',
        29: 'Jarmuth und ihr Weichbild, En-Gannim und ihr Weichbild, vier Städte.',
        30: 'Und vom Stamme Ascher Mischal und ihr Weichbild, Abdon und ihr Weichbild,',
        31: 'Chelkath und ihr Weichbild, und Rechob und ihr Weichbild, vier Städte.',
        32: 'Und vom Stamme Naphthali die Zufluchtsstadt für den Totschläger: Kedesch im Galil und ihr Weichbild, und ChammothDor und ihr Weichbild, und Karthan und ihr Weichbild, drei Städte.',
        33: 'Alle Städte der Gerschumiter nach ihren Familien waren dreizehn Städte und ihre Weichbilder.',
        34: 'Und den Familien der Söhne Meraris, den Leviten, die noch übrig waren vom Stamme Sebulun: Jokneam und ihr Weichbild, Karthah und ihr Weichbild.',
        35: 'Dimnah und ihr Weichbild, und Nahalal und ihr Weichbild, vier Städte.',
        36: 'Und vom Stamme Ruben: Bezer und ihr Weichbild, und Jahzah und ihr Weichbild,',
        37: 'Kedemoth und ihr Weichbild, und Mephaath und ihr Weichbild, vier Städte.',
        38: 'Und vom Stamme Gad die Zufluchtsstadt für den Totschläger: Ramoth in Gilead und ihr Weichbild und Machanajim und ihr Weichbild,',
        39: 'Cheschbon und ihr Weichbild, und Jaser und ihr Weichbild; aller Städte waren es vier.',
        40: 'Alle Städte der Söhne Meraris nach ihren Familien, die übrig waren von den Familien der Leviten, und ihr Los waren zwölf Städte.',
        41: 'Alle Städte der Leviten in der Mitte des Eigentums der Söhne Israels waren achtundvierzig Städte und ihre Weichbilder.',
        42: 'Dies waren die Städte, jede Stadt und ihr Weichbild rings um sie her. So war es bei allen diesen Städten.',
        43: 'Und Jehovah gab Israel das ganze Land, das Er seinen Vätern zu geben geschworen hatte, und sie nahmen es ein und wohnten darin.',
        44: 'Und Jehovah ließ sie ruhen von denen ringsum, nach allem, das Er ihren Vätern geschworen hatte. Und kein Mann stand vor ihnen von allen ihren Feinden. Alle ihre Feinde gab Jehovah in ihre Hand;',
        45: 'Und es fiel kein Wort von all dem guten Worte, das Jehovah zu dem Hause Israel geredet hatte, alles kam zu.',
    },
    22: {
        1: 'Nun rief Joschua den Rubeniten und den Gaditen und den halben Stamm Menascheh,',
        2: 'Und sprach zu ihnen: Ihr habt alles gehalten, was euch Mose, der Knecht Jehovahs, geboten, und habt gehört auf meine Stimme in allem, was ich euch gebot.',
        3: 'Ihr habt diese vielen Tage eure Brüder nicht verlassen bis auf diesen Tag, und die Verordnung, das Gebot Jehovahs, eures Gottes, gehalten.',
        4: 'Und nun läßt Jehovah, euer Gott, eure Brüder ruhen, wie Er zu ihnen geredet hatte. So wendet euch denn und ziehet auch nach euren Zelten in das Land eures Eigentums, das euch Mose, der Knecht Jehovahs, jenseits des Jordan gegeben hat.',
        5: 'Nur hütet euch sehr, daß ihr tut das Gebot und das Gesetz, das euch Mose, der Knecht Jehovahs, geboten hat, daß ihr liebet Jehovah, euren Gott, und in all Seinen Wegen wandelt und haltet Seine Gebote, und Ihm dienet von eurem ganzen Herzen und von eurer ganzen Seele.',
        6: 'Und Joschua segnete sie und entließ sie, und sie zogen nach ihren Zelten.',
        7: 'Und dem einen halben Stamm Menascheh hatte Mose in Baschan gegeben, und dem anderen halben gab Joschua mit ihren Brüdern diesseits des Jordan dem Meere zu; und als Joschua sie entließ zu ihren Zelten, segnete er sie auch,',
        8: 'Und sprach zu ihnen und sagte: Kehret zurück zu euren Zelten mit vielem Wohlstand und mit sehr vielen Viehherden, mit Silber und mit Gold, und mit Erz und mit Eisen und mit sehr vielen Gewändern. Teilet die Beute von euren Feinden mit euren Brüdern.',
        9: 'Und sie kehrten zurück, die Söhne Rubens und die Söhne Gads und der halbe Stamm Menascheh, und sie gingen von den Söhnen Israels von Schiloh im Lande Kanaan, daß sie in das Land Gilead in das Land ihres Eigentums zogen, das sie nach dem Befehl Jehovahs durch Moses Hand zum Eigentum hatten.',
        10: 'Und sie kamen in die Kreise des Jordans, im Lande Kanaan, und die Söhne Rubens und die Söhne Gads und der halbe Stamm Menascheh bauten allda am Jordan einen Altar, einen Altar groß zum Ansehen.',
        11: 'Und die Söhne Israels hörten sagen: Siehe, die Söhne Rubens und die Söhne Gads und der halbe Stamm Menascheh haben den Altar gebaut dem Lande Kanaan gegenüber, in den Kreisen des Jordans, jenseits der Söhne Israels.',
        12: 'Und die Söhne Israels hörten es, und es versammelte sich die ganze Gemeinde der Söhne Israels nach Schiloh, um wider sie hinaufzuziehen zum Heerzug.',
        13: 'Und die Söhne Israels sandten an die Söhne Rubens und an die Söhne Gads und an den halben Stamm Menascheh nach dem Lande Gilead, Pinechas, den Sohn Eleasars, des Priesters,',
        14: 'Und zehn Fürsten mit ihm, je einen Fürsten auf das Vaterhaus für alle Stämme Israels, und deren jeder Mann das Haupt des Hauses seiner Väter unter den Tausenden Israels.',
        15: 'Und sie kamen zu den Söhnen Rubens und zu den Söhnen Gads und zu dem halben Stamm Menascheh, nach dem Lande Gilead und redeten mit ihnen und sprachen:',
        16: 'Also hat die ganze Gemeinde Jehovahs gesprochen: Was ist diese Untreue, daß ihr dem Gotte Israels untreu geworden seid, daß ihr euch heute von Jehovah zurückgewendet, indem ihr euch einen Altar gebaut habt, so daß ihr euch heute wider Jehovah empört habt?',
        17: 'Ist es uns zu wenig an der Missetat von Peor, von der wir uns nicht gereinigt bis auf diesen Tag und ob der die Plage über die Gemeinde Jehovahs kam?',
        18: 'Und ihr wendet euch heute von Jehovah zurück und empört euch heute wider Jehovah, so daß Er morgen über die ganze Gemeinde Israel Sich entrüste.',
        19: 'Und wenn ja das Land eures Eigentums unrein ist, so ziehet herüber in das Land des Eigentums Jehovahs, wo die Wohnung Jehovahs wohnt, und habt Eigentum in unserer Mitte, und empört euch nicht wider Jehovah, und empört euch nicht wider uns, daß ihr euch einen Altar baut außer dem Altar unseres Gottes Jehovah.',
        20: 'Hat nicht Achan, der Sohn Serachs ob dem Bann eine Untreue begangen, und war da nicht über die ganze Gemeinde eine Entrüstung, so daß nicht nur der eine Mann ob seiner Missetat verscheiden mußte?',
        21: 'Und die Söhne Rubens und die Söhne Gads und der halbe Stamm Menascheh antworteten und redeten mit den Häuptern der Tausende Israels:',
        22: 'Der Gott der Götter, Jehovah, der Gott der Götter Jehovah, Er weiß es, und Israel, es soll es wissen: Wenn es Empörung und wenn es Untreue gegen Jehovah war - dann mögest Du an diesem Tag uns nicht retten!',
        23: 'Daß wir uns einen Altar bauten, um von Jehovah uns zurückzuwenden, und wenn es geschah, um darauf Brandopfer und Speiseopfer aufzuopfern, um darauf Dankopfer zu schlachten, so möge Jehovah es fordern!',
        24: 'Und wenn wir das nicht taten aus Besorgnis für die Sache, daß wir sagten: Morgen könnten eure Söhne sprechen zu unseren Söhnen und sagen: Was geht euch Jehovah, der Gott Israels an?',
        25: 'Und Jehovah hat eine Grenze zwischen uns und euch, ihr Söhne Rubens und Söhne Gads, den Jordan, gesetzt. Ihr habt keinen Teil an Jehovah, und es möchten eure Söhne unsere Söhne abbringen von der Furcht Jehovahs.',
        26: 'Und wir sprachen: Lasset uns doch das für uns tun, daß wir den Altar bauen, nicht zum Brandopfer und nicht zum Schlachtopfer;',
        27: 'Sondern daß er ein Zeuge sei zwischen uns und euch und zwischen unseren Geschlechtern nach uns, auf daß wir den Dienst Jehovahs dienen vor Ihm mit unseren Brandopfern und mit unseren Schlachtopfern und mit unseren Dankopfern, auf daß eure Söhne nicht morgen sagen zu unseren Söhnen: Ihr habt kein Teil an Jehovah!',
        28: 'Und wir sprachen: Wenn es dennoch geschieht, daß sie so zu uns und zu unseren Geschlechtern morgen sprechen, so werden wir sagen: sehet das Muster von Jehovahs Altar, das unsere Väter gemacht, nicht zum Brandopfer, noch zum Schlachtopfer, sondern daß er ein Zeuge sei zwischen uns und euch!',
        29: 'Das sei ferne von uns, daß wir uns wider Jehovah empörten und heute von Jehovah uns zurückwendeten und einen Altar erbaueten zum Brandopfer, zum Speiseopfer und zum Schlachtopfer außer dem Altare Jehovahs, unseres Gottes, Der vor Seiner Wohnung ist!',
        30: 'Und es hörte Pinechas, der Priester, und die Fürsten der Gemeinde und die Häupter der Tausende Israels, die mit ihm waren, die Worte, welche die Söhne Rubens und die Söhne Gads und die Söhne Menaschehs redeten; und es war gut in ihren Augen.',
        31: 'Und Pinechas, der Sohn Eleasars, des Priesters, sprach zu den Söhnen Rubens und zu den Söhnen Gads und zu den Söhnen Menaschehs: Heute wissen wir, daß Jehovah in unserer Mitte ist, weil ihr nicht diese Untreue an Jehovah begangen habt. Nun habt ihr die Söhne Israels aus der Hand Jehovahs errettet.',
        32: 'Und Pinechas, der Sohn Eleasars, des Priesters, und die Fürsten kehrten von den Söhnen Rubens und von den Söhnen Gads aus dem Lande Gilead zurück ins Land Kanaan zu den Söhnen Israels und brachten ihnen das Wort zurück.',
        33: 'Und das Wort war gut in den Augen der Söhne Israels, und die Söhne Israels segneten Gott und sprachen nicht mehr, man müßte wider sie hinaufziehen zum Heerzug und das Land verderben, darin die Söhne Rubens und die Söhne Gads wohnten.',
        34: 'Und die Söhne Rubens und die Söhne Gads nannten den Altar: Er ist Zeuge zwischen uns, daß Jehovah ist Gott.',
    },
    23: {
        1: 'Und es geschah nach vielen Tagen, nachdem Jehovah Israel von allen seinen Feinden ringsumher zur Ruhe gebracht, und Joschua alt und betagt war,',
        2: 'Da rief Joschua ganz Israel, seine Ältesten und seine Häupter und seine Richter und seine Vorsteher und sprach zu ihnen: Ich bin alt geworden und betagt,',
        3: 'Und ihr habt gesehen alles, was Jehovah, euer Gott, all diesen Völkerschaften vor euch her getan hat; denn Jehovah, euer Gott, war es, Der für euch stritt.',
        4: 'Sehet, ich habe euch diese Völkerschaften, die verbleiben, nach euren Stämmen zum Erbe zufallen lassen, vom Jordan an, und alle Völkerschaften, die ich ausgerottet habe, bis an das große Meer, wo die Sonne untergeht.',
        5: 'Und Jehovah, euer Gott, Er wird sie vertreiben, vor euch her und sie vor euch austreiben, daß ihr deren Land einnehmet, wie Jehovah, euer Gott, zu euch geredet hat.',
        6: 'So seid denn sehr stark und haltet und tut alles, was in Moses Buche des Gesetzes geschrieben ist, daß ihr davon nicht abweichet weder zur Rechten, noch zur Linken;',
        7: 'Auf daß ihr nicht unter diese Völkerschaften eingeht, die noch bei euch verbleiben, und nicht des Namens ihrer Götter gedenkt, noch bei ihnen schwört und ihnen nicht dient, noch sie anbetet;',
        8: 'Sondern nur Jehovah, eurem Gotte, anhanget, wie ihr getan habt bis auf diesen Tag.',
        9: 'Und Jehovah trieb große und mächtige Völkerschaften vor euch aus, und ihr, kein Mann bestand vor euch, bis auf diesen Tag.',
        10: 'Ein Mann von euch setzt Tausenden nach; denn Jehovah, euer Gott, ist es, Der für euch streitet, wie Er zu euch geredet hat.',
        11: 'So hütet euch sehr für eure Seelen, daß ihr Jehovah, euren Gott, liebt.',
        12: 'Denn wenn ihr euch wieder zurückwendet und euch hängt an diese übrigen Völkerschaften, die unter euch verblieben, und euch verschwägert mit ihnen und unter sie eingehet und sie unter euch;',
        13: 'So werdet ihr erfahren, daß Jehovah, euer Gott, diese Völkerschaften nicht ferner austreibt vor euch, daß sie euch zur Schlinge und zum Fallstrick werden und zur Geißel an euren Seiten und zu Stacheln in euren Augen, bis daß ihr umkommt von diesem guten Boden, den euch Jehovah, euer Gott, gegeben hat.',
        14: 'Und siehe, ich gehe heute den Weg aller Erde; ihr aber sollt wissen von eurem ganzen Herzen und von eurer ganzen Seele, daß kein einziges Wort von all den guten Worten, die Jehovah, euer Gott, über euch geredet hat, weggefallen, daß alle über euch gekommen sind, kein einziges Wort davon ist weggefallen.',
        15: 'Und es wird geschehen, daß, sowie jedes gute Wort, das Jehovah, euer Gott, zu euch geredet hat, über euch kam, so Jehovah über euch jedes böse Wort kommen läßt, bis daß Er euch von diesem guten Boden, den euch Jehovah, euer Gott, gegeben hat, vernichtet hat.',
        16: 'So ihr den Bund Jehovahs, eures Gottes, überschreitet, den Er euch geboten, und hingeht und anderen Göttern dient und sie anbetet, so wird der Zorn Jehovahs wider euch entbrennen, und ihr werdet eilends umkommen von dem guten Land, das Er euch gegeben hat.',
    },
    24: {
        1: 'Und Joschua versammelte alle Stämme Israels nach Schechem und rief den Ältesten Israels, seinen Häuptern und seinen Richtern und seinen Vorstehern, und sie stellten sich vor Gott;',
        2: 'Und Joschua sprach zu dem ganzen Volke: So sprach Jehovah, der Gott Israels: Jenseits des Flusses wohnten vor Zeiten eure Väter Terach, der Vater Abrahams und der Vater Nachors und dienten anderen Göttern.',
        3: 'Und Ich nahm euren Vater Abraham von jenseits des Flusses und ließ ihn ziehen durch das ganze Land Kanaan und mehrte seinen Samen und gab ihm den Isaak.',
        4: 'Und dem Isaak gab Ich Jakob und Esau; und dem Esau gab Ich das Gebirge Seir, es erblich zu besitzen, und Jakob und seine Söhne gingen hinab nach Ägypten.',
        5: 'Und Ich sandte Mose und Aharon und schlug Ägypten. Wie Ich so getan in seiner Mitte, führte Ich euch danach aus;',
        6: 'Und Ich führte eure Väter aus von Ägypten, und ihr kamt an das Meer. Und die Ägypter setzten euren Vätern nach mit Streitwagen und Reitern an das Schilfmeer.',
        7: 'Und sie schrien zu Jehovah, und Er setzte Dunkelheit zwischen euch und die Ägypter, und brachte über sie das Meer herein, daß es sie bedeckte; und eure Augen sahen, was Ich an Ägypten getan, und viele Tage wohntet ihr in der Wüste.',
        8: 'Und Ich brachte euch nach dem Lande des Amoriters, der jenseits des Jordan wohnte und sie stritten mit euch. Und Ich gab sie in eure Hand, und ihr nahmt ihr Land ein, und Ich vernichtete sie vor euch her.',
        9: 'Und Balak machte sich auf, der Sohn Zippors, Moabs König, und stritt mit Israel, und sandte und rief Bileam, Beors Sohn, daß er euch fluchete;',
        10: 'Und Ich wollte nicht hören auf Bileam, und er segnete euch, und Ich errettete euch aus seiner Hand.',
        11: 'Und ihr setztet über den Jordan und kamt nach Jericho; und es stritten wider euch die Bürger von Jericho, der Amoriter und der Pherisiter und der Kanaaniter und der Chethiter und der Girgaschiter, der Chiviter und der Jebusiter, und Ich gab sie in eure Hand.',
        12: 'Und Ich sandte die Hornisse vor euch her und Ich trieb sie fort vor Euch, die zwei Könige des Amoriters, nicht mit deinem Schwert und nicht mit deinem Bogen.',
        13: 'Und Ich habe euch ein Land gegeben, um das du dich nicht bemüht hast, und die Städte, die ihr nicht gebaut, und ihr wohnt darin; von Weinbergen und Ölgärten, die ihr nicht gepflanzt habt, esset ihr.',
        14: 'Und nun fürchtet Jehovah und dient Ihm untadelig und mit Treue, und wendet euch ab von den Göttern, denen eure Väter jenseits des Flusses und in Ägypten gedient, und dienet Jehovah!',
        15: 'Ist es aber böse in euren Augen, daß ihr Jehovah dient, so erwählet heute für euch, wem ihr dienen wollt; ob den Göttern, denen eure Väter, die jenseits des Flusses waren, gedient, oder den Göttern des Amoriters, in dessen Lande ihr wohnt; ich aber und mein Haus, wir werden Jehovah dienen.',
        16: 'Und das Volk antwortete und sprach: Ferne sei von uns, daß wir Jehovah verließen, um anderen Göttern zu dienen.',
        17: 'Ist es ja Jehovah, unser Gott, Der uns heraufgeführt und unsere Väter aus Ägyptenland und aus der Knechte Haus, und Der vor unseren Augen diese großen Zeichen getan und uns behütet hat auf dem ganzen Wege, auf dem wir gegangen, und unter allen Völkern, durch deren Mitte wir gezogen sind.',
        18: 'Und Jehovah trieb fort vor uns alle die Völker und den Amoriter, der im Lande wohnte. Darum wollen auch wir Jehovah dienen; denn Er ist unser Gott.',
        19: 'Und Joschua sprach zu dem Volk: Ihr werdet Jehovah nicht zu dienen vermögen; denn Er ist ein heiliger Gott, ein eifernder Gott, Der euch eure Übertretungen und Sünden nicht verzeihen wird.',
        20: 'Wenn ihr Jehovah verlasset und Göttern des Auslandes dient, so wird Er Sich zurückwenden und euch Übles tun und euch verzehren, nachdem Er euch Gutes getan hat.',
        21: 'Und das Volk sprach zu Joschua: Nein, sondern Jehovah wollen wir dienen.',
        22: 'Und Joschua sprach zum Volk: Ihr selbst seid Zeugen gegen euch, daß ihr Jehovah für euch erwählt habt, Ihm zu dienen. Und sie sprachen: Wir sind Zeugen.',
        23: 'Und nun tut weg von euch die Götter des Auslandes, die in eurer Mitte sind, und neigt euer Herz zu Jehovah, dem Gott Israels.',
        24: 'Und das Volk sprach zu Joschua: Jehovah, unserem Gott, werden wir dienen und auf Seine Stimme hören.',
        25: 'Und Joschua schloß selbigen Tages für das Volk einen Bund und setzte ihm Satzung und Recht in Schechem.',
        26: 'Und Joschua schrieb diese Worte in das Buch des Gesetzes Gottes und nahm einen großen Stein und richtete ihn allda auf unter der Eiche, die am Heiligtum Jehovahs war.',
        27: 'Und Joschua sprach zu allem Volk: Siehe, dieser Stein soll gegen uns zum Zeugen sein, daß er hörte all die Reden Jehovahs, die Er mit uns geredet hat, und soll zum Zeugen sein wider euch, auf daß ihr euren Gott nicht verleugnet.',
        28: 'Und Joschua entließ das Volk, jeden Mann in sein Erbe.',
        29: 'Und nach diesen Dingen geschah, daß Joschua, der Sohn Nuns, der Knecht Jehovahs, starb, einhundertzehn Jahre alt.',
        30: 'Und sie begruben ihn in der Grenze seines Erbes in Timnath-Serach, auf dem Gebirge Ephraim, nördlich vom Berge Gaasch.',
        31: 'Und Israel diente Jehovah all die Tage Joschuas und all die Tage der Ältesten, deren Tage verlängert wurden nach Joschua, und die um alle Taten Jehovahs wußten, die Er für Israel tat.',
        32: 'Und die Gebeine Josephs, welche die Söhne Israel aus Ägypten heraufgebracht, begruben sie in Schechem in dem Teile des Feldes, das Jakob von den Söhnen Chamors, des Vaters Schichems, um hundert Kesitah gekauft hatte, und sie waren Josephs Söhnen zum Erbe.',
        33: 'Und Eleasar, der Sohn Aharons, starb, und sie begruben ihn in Gibeah des Pinechas, seines Sohnes, das ihm auf dem Gebirge Ephraims gegeben ward.',
    },
}
